// 3 Царств — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Коли цар Давид постарів, увійшов у похилі літа, то покривали його одягом, але він не міг зігрітися.","І сказали йому слуги його: нехай пошукають для господаря нашого царя молоду дівчину, щоб вона була з царем і доглядала за ним і лежала з ним, — і буде тепло господарю нашому, цареві.","І шукали красиву дівчину у всіх краях Ізраїльських, і знайшли Ависагу сунамитянку, і привели її до царя.","Дівчина була дуже красива, і доглядала вона за царем і прислуговувала йому; але цар не пізнав її.","Адонія, син Аггифи, загордувавши, говорив: я буду царем. І завів собі колісниці і вершників і п’ятдесят чоловік скороходів.","Батько ж ніколи не утруднював його запитанням: для чого ти це робиш? Він же був дуже красивий і народився у нього після Авессалома.","І радився він з Іоавом, сином Саруїним, і з Авиафаром священиком, і вони допомагали Адонії.","Але священик Садок і Ванея, син Іодаїв, і пророк Нафан, і Семей, і Рисій, і сильні Давидові не були на боці Адонії.","І заколов Адонія овець і волів і тельців біля каменя Зохелет, що біля джерела Рогель, і запросив усіх братів своїх, синів царя, із усіма юдеянами, які служили у царя.","Пророка ж Нафана і Ванею, і тих сильних, і Соломона, брата свого, не запросив.","Тоді Нафан сказав Вирсавії, матері Соломона, говорячи: чи чула ти, що Адонія, син Аггифин, зробився царем, а цар наш Давид не знає про це?","Тепер, ось, я раджу тобі: рятуй життя твоє і життя сина твого Соломона.","Йди і ввійди до царя Давида і скажи йому: чи не клявся ти, господарю мій царю, рабі твоїй, говорячи: «син твій Соломон буде царем після мене і він сяде на престолі моєму»? Чому ж воцарився Адонія?","І ось, коли ти ще будеш говорити там з царем, ввійду і я слідом за тобою і доповню слова твої.","Вирсавія ввійшла до царя в спальню; цар був дуже старий, і Ависага сунамитянка прислуговувала цареві;","і нахилилася Вирсавія і поклонилася цареві; і сказав цар: що тобі?","Вона сказала йому: господарю мій царю! ти клявся рабі твоїй Господом Богом твоїм: «син твій Соломон буде царювати після мене і він сяде на престолі моєму».","А тепер, ось, Адонія став царем , і ти, господарю мій царю, не знаєш про це.","І заколов він багато волів, тельців і овець, і запросив усіх синів царських і священика Авиафара, і воєначальника Іоава; Соломона ж, раба твого, не запросив.","Але ти, господарю мій, — цар, і очі всіх ізраїльтян звернені на тебе, щоб ти оголосив їм, хто сяде на престолі господаря мого царя після нього;","інакше, коли господар мій цар спочине з батьками своїми, впаде звинувачення на мене і на сина мого Соломона.","Коли вона ще говорила з царем, прийшов і пророк Нафан.","І сказали цареві, говорячи: ось Нафан пророк. І увійшов він до царя і поклонився цареві лицем до землі.","І сказав Нафан: господарю мій царю! чи сказав ти: «Адонія буде царювати після мене і він сяде на престолі моєму»?","Тому що він нині зійшов і заколов багато волів, тельців і овець, і запросив усіх синів царських і воєначальників і священика Авиафара, і ось, вони їдять і п’ють у нього і говорять: нехай живе цар Адонія!","А мене, раба твого, і священика Садока, і Ванею, сина Іодаєвого, і Соломона, раба твого, не запросив.","Чи не сталося це з волі господаря мого царя, і чому ти не відкрив рабу твоєму, хто сяде на престолі господаря мого царя після нього?","І відповів цар Давид і сказав: покличте до мене Вирсавію. І увійшла вона і стала перед царем.","І клявся цар і сказав: живий Господь, Який спасав душу мою від усякого лиха!","Як я клявся тобі Господом Богом Ізраїлевим, говорячи, що Соломон, син твій, буде царювати після мене, і він сяде на престолі моєму замість мене, так я і зроблю це сьогодні.","І нахилилася Вирсавія лицем до землі, і поклонилася цареві, і сказала: нехай живе господар мій цар Давид повіки!","І сказав цар Давид: покличте до мене священика Садока і пророка Нафана і Ванею, сина Іодаєвого. І увійшли вони до царя.","І сказав їм цар: візьміть із собою слуг господаря вашого і посадіть Соломона, сина мого, на мула мого, і привезіть його до Гиона,","і нехай помаже його там Садок священик і Нафан пророк на царя над Ізраїлем, і засурміть трубою і виголосіть: нехай живе цар Соломон!","Потім проведіть його назад, і він прийде і сяде на престолі моєму; він буде царювати замість мене; йому заповідав я бути вождем Ізраїля й Іуди.","І відповів Ванея, син Іодаїв, царю і сказав: амінь, — нехай скаже так Господь Бог господаря мого царя!","Як був Господь Бог з господарем моїм царем, нехай так буде Він і з Соломоном і нехай звеличить престіл його більше за престіл господаря мого царя Давида!","І пішли Садок священик і Нафан пророк і Ванея, син Іодая, і хелефеї і фелефеї, і посадили Соломона на мула царя Давида, і повезли його до Гиона.","І взяв Садок священик ріг з єлеєм зі скинії і помазав Соломона. І засурмили трубою, і весь народ викликував: нехай живе цар Соломон!","І весь народ проводжав Соломона, і грав народ на сопілках, і дуже радів, так що земля розсідалася від криків його.","І почув Адонія і всі запрошені ним, як тільки перестали їсти; а Іоав, почувши звук труби, сказав: від чого цей шум міста, що розхвилювалося?","Ще він говорив, як прийшов Іоанафан, син священика Авиафара. І сказав Адонія: увійди; ти — чесна людина і несеш добру звістку.","І відповів Іонафан і сказав Адонії: так, господар наш цар Давид поставив Соломона царем;","і послав цар з ним Садока священика і Нафана пророка, і Ванею, сина Іодая, і хелефеїв і фелефеїв, і вони посадили його на мула царського;","і помазали його Садок священик і Нафан пророк на царя в Гионі, і звідти вирушили з радістю, і прийшло у рух місто. Ось від чого шум, який ви чуєте.","І Соломон уже сів на царському престолі.","І слуги царя приходили поздоровити господаря нашого царя Давида, говорячи: Бог твій нехай прославить ім’я Соломона більше за твоє ім’я і нехай звеличить престіл його більше за твій престіл. І поклонився цар на ложі своєму,","і сказав цар так: «благословенний Господь Бог Ізраїлів, Який сьогодні дав [від сімені мого] того, хто сидить на престолі моєму, і очі мої бачать це!»","Тоді злякалися і встали всі запрошені, які були в Адонії, і пішли кожен своєю дорогою.","Адонія ж, боячись Соломона, встав і пішов і схопився за роги жертовника.","І донесли Соломону, говорячи: ось, Адонія боїться царя Соломона, і ось, він тримається за роги жертовника, говорячи: нехай поклянеться мені тепер цар Соломон, що він не умертвить раба свого мечем.","І сказав Соломон: якщо він буде людиною чесною, то жодна волосина його не впаде на землю; якщо ж знайдеться в ньому лукавство, то помре.","І послав цар Соломон, і привели його від жертовника. І він прийшов і поклонився цареві Соломону; і сказав йому Соломон: іди в дім свій."],"x":{"3":"5.19.18|10.2.17|11.4.8","5":"9.3.4|12.3.2","6":"9.3.4","7":"10.2.22","8":"12.23.7","9":"0.31.54|5.15.7|9.17.17","11":"13.9.29","13":"1.11.5","17":"9.12.24|12.28.5","23":"9.24.20","25":"8.10.24","29":"9.4.9","30":"10.3.6","33":"0.41.43|12.23.1|13.32.30","34":"8.10.1|10.19.15","35":"12.23.1","36":"12.22.9","38":"9.8.18","39":"1.30.25|11.11.12|50.21.9","42":"9.15.27","44":"10.1.38","47":"0.47.31","50":"1.27.2","51":"10.2.28","52":"8.14.45|52.12.7|54.27.34"}},{"v":["Наблизився час помирати Давиду, і заповідав він синові своєму Соломону, говорячи:","ось, я відходжу в путь усієї землі, ти ж будь твердим і будь мужнім","і зберігай завіт Господа Бога твого, ходячи путями Його і дотримуючись уставів Його і заповідей Його, і визначень Його і постанов Його, як написано в законі Мойсеєвому, щоб бути тобі розсудливим у всьому, що будеш робити, і скрізь, куди звернешся;","щоб Господь виконав слово Своє, яке Він сказав про мене, говорячи: «якщо сини твої будуть стежити за путями своїми, щоб ходити переді Мною в істині від усього серця свого і від усієї душі своєї, то не припиниться муж від тебе на престолі Ізраїлевім».","Ще: ти знаєш, що зробив мені Іоав, син Саруїн, як учинив він із двома вождями війська ізраїльського, з Авениром, сином Нировим, і Амессаєм, сином Ієферовим, як він умертвив їх і пролив кров бранну під час миру, обагривши кров’ю бранною пояс на стегнах своїх і взуття на ногах своїх:","вчини за мудрістю твоєю, щоб не відпустити сивини його мирно в пекло.","А синам Верзеллія галаадитянина зроби милість, щоб вони були між тими, хто годується за твоїм столом, бо вони прийшли до мене, коли я втікав від Авессалома, брата твого.","Ось ще в тебе Семей, син Гери веніамитянина з Бахурима; він лихословив мене тяжким лихослів’ям, коли я йшов у Маханаїм; але він вийшов назустріч мені біля Йордану, і я поклявся йому Господом, говорячи: «я не умертвлю тебе мечем».","Ти ж не залиш його безкарним; бо ти людина мудра і знаєш, що тобі зробити з ним, щоб звести сивину його у крові в пекло.","І спочив Давид з батьками своїми і похований був у місті Давидовому.","Царював Давид над Ізраїлем сорок років: у Хевроні царював він сім років і тридцять три роки царював у Єрусалимі.","І сів Соломон на престолі Давида, батька свого, і царювання його було дуже міцним.","І прийшов Адонія, син Аггифи, до Вирсавії, матері Соломона, [і поклонився їй]. Вона сказала: чи з миром прихід твій? І сказав він: з миром.","І сказав він: у мене є слово до тебе. Вона сказала: говори.","І сказав він: ти знаєш, що царство належало мені, і весь Ізраїль звертав на мене погляди свої, як на майбутнього царя; але царство відійшло від мене і дісталося братові моєму, бо це було йому від Господа;","тепер я прошу тебе про одне, не відмов мені. Вона сказала йому: говори.","І сказав він: прошу тебе, поговори з царем Соломоном, бо він не відмовить тобі, щоб він дав мені Ависагу сунамитянку за дружину.","І сказала Вирсавія: добре, я поговорю про тебе з царем.","І увійшла Вирсавія до царя Соломона говорити йому про Адонію. Цар встав перед нею, і поклонився їй, і сів на престолі своєму. Поставили престіл і для матері царя, і вона сіла праворуч від нього","і сказала: я маю до тебе одне невелике прохання, не відмов мені. І сказав їй цар: проси, мати моя; я не відмовлю тобі.","І сказала вона: дай Ависагу сунамитянку Адонії, братові твоєму, за дружину.","І відповідав цар Соломон і сказав матері своїй: а навіщо ти просиш Ависагу сунамитянку для Адонії? проси йому також і царство; тому що він мій старший брат, і йому священик Авиафар і Іоав, син Саруїн, [воєначальник, друг].","І поклявся цар Соломон Господом, говорячи: те і те нехай зробить зі мною Бог і ще більше зробить, якщо не на свою душу сказав Адонія таке слово;","нині ж, — живий Господь, Який укріпив мене і посадив мене на престолі Давида, батька мого, і Який влаштував мені дім, як говорив Він, — нині ж Адонія повинен померти.","І послав цар Соломон Ванею, сина Іодаєвого, який уразив його, і він помер.","А священику Авиафару цар сказав: іди в Анафоф на твоє поле; ти гідний смерти, але в даний час я не умертвлю тебе, бо ти носив ковчег Владики Господа перед Давидом, батьком моїм, і терпів усе, що терпів батько мій.","І відсторонив Соломон Авиафара від священства Господнього, і сповнилося слово Господа, яке сказав Він про дім Ілія в Силомі.","Чутка про це дійшла до Іоава, — бо Іоав схилявся на бік Адонії, а на бік Соломона не схилявся, — і втік Іоав у скинію Господню і схопився за роги жертовника.","І донесли царю Соломону, що Іоав утік у скинію Господню і що він біля жертовника. І послав Соломон Ванею, сина Іодаєвого, говорячи: піди, умертви його [і поховай його].","І прийшов Ванея в скинію Господню і сказав йому: так сказав цар: виходь. І сказав той: ні, я хочу померти тут. Ванея передав це царю, говорячи: так сказав Іоав, і так відповів мені.","Цар сказав йому: зроби, як він сказав, і умертви його і поховай його, і зніми невинну кров, пролиту Іоавом, з мене і з дому батька мого;","нехай поверне Господь кров його на голову його за те, що він убив двох мужів невинних і кращих за нього: вразив мечем, без відома батька мого Давида, Авенира, сина Нирового, воєначальника ізраїльського, і Амессая, сина Ієферового, воєначальника юдейського;","нехай обернеться кров їх на голову Іоава і на голову потомства його повіки, а Давиду і потомству його, і дому його і престолу його нехай буде мир навіки від Господа!","І пішов Ванея, син Іодаїв, і вразив Іоава, і умертвив його, і він був похований у домі своєму в пустелі.","І поставив цар Соломон Ванею, сина Іодаєвого, замість нього над військом; [управління ж царством було в Єрусалимі,] а Садока священика поставив цар [первосвящеником] замість Авиафара. [І дав Господь Соломону розуміння і мудрість дуже велику і обширний розум, як пісок при морі. І Соломон мав розум вище за розум усіх синів сходу і всіх мудрих єгиптян. І взяв за себе дочку фараона і ввів її в місто Давидове, доки не побудував дому свого і, по-перше, дому Господнього і стіни навколо Єрусалима; за сім років закінчив він будівництво. І було у Соломона сімдесят тисяч чоловік, які носили важкі речі, і вісімдесят тисяч каменосіків у горах. І зробив Соломон море і підпори, і великі лазні і стовпи, і джерело надворі і мідне море, і побудував замок і укріплення його, і розділив місто Давидове. Тоді дочка фараона перейшла з міста Давидового в дім свій, який він побудував їй; тоді побудував Соломон стіну навколо міста. І приносив Соломон тричі на рік всепалення і мирні жертви на жертовнику, який він спорудив Господу, і куріння звершував на ньому перед Господом, і закінчив будівництво дому. Головних приставників над роботами Соломоновими було три тисячі шістсот, які керували народом, що виконував роботи. І побудував він Ассур, і Магдон, і Газер, і Вефорон вишній і Валалаф; але ці міста він побудував після побудови дому Господнього і стіни навколо Єрусалима. І ще за життя Давид заповідав Соломону, говорячи: ось у тебе Семей, син Гери, сина Ієминиїного з Бахурима; він лихословив мене тяжким лихослів’ям, коли я йшов у Маханаїм; але він вийшов назустріч мені біля Йордану, і я присягнув йому Господом, говорячи: «я не умертвлю тебе мечем». Ти ж не залиш його безкарним, бо ти людина мудра і знаєш, що тобі зробити з ним, щоб звести сивину його в крові у пекло.]","І послав цар і покликав Семея і сказав йому: побудуй собі дім в Єрусалимі і живи тут, і нікуди не виходь звідси;","і знай, що в той день, у який ти вийдеш і перейдеш потік Кедрон, неодмінно помреш; кров твоя буде на голові твоїй.","І сказав Семей цареві: добре; як наказав господар мій цар, так зробить раб твій. І жив Семей в Єрусалимі довгий час.","Але через три роки трапилося, що у Семея двоє рабів утекли до Анхуса, сина Маахи, царя Гефського. І сказали Семею, говорячи: ось, раби твої в Гефі.","І встав Семей, і осідлав осла свого, і вирушив у Геф до Анхуса шукати рабів своїх. І повернувся Семей і привів рабів своїх з Гефа.","І донесли Соломону, що Семей ходив з Єрусалима у Геф і повернувся.","І пославши, покликав цар Семея і сказав йому: чи не клявся я тобі Господом і чи не оголошував тобі, говорячи: «знай, що в той день, у який ти вийдеш і підеш куди-небудь, неодмінно помреш»? і ти сказав мені: «добре»;","навіщо ж ти не дотримав наказу, який я дав тобі перед Господом із клятвою?","І сказав цар Семею: ти знаєш і знає серце твоє все зло, яке ти зробив батькові моєму Давиду; нехай же поверне Господь злість твою на голову твою!","а цар Соломон нехай буде благословенний, і престіл Давида нехай буде непохитним перед Господом повіки!","і повелів цар Ванеї, синові Іодаєвому, і він пішов і вразив Семея, і той помер."],"x":{"2":"5.23.14","3":"5.22.3|12.28.9","4":"25.131.12|10.8.23:25","5":"9.3.27","7":"9.19.31","8":"9.16.13|10.2.23","10":"54.2.29|54.13.36","11":"9.5.4|12.29.26","12":"12.29.23","15":"10.1.5|12.22.9","17":"10.1.3-4","22":"10.1.7","24":"9.7.12:27","26":"5.21.18|32.1.1|3.4.15","27":"8.2.31","28":"10.1.50","31":"1.21.14|9.23.20","32":"9.3.27:37","33":"0.9.6|50.26.52|76.13.10","34":"9.3.39","35":"10.2.8","37":"9.15.23|11.23.4|53.18.1","39":"8.21.10","44":"9.16.5","45":"21.2.57"}},{"v":["[Коли утвердилося царство в руках Соломона,] Соломон поріднився з фараоном, царем Єгипетським і взяв за себе дочку фараона і ввів її в місто Давидове, доки не побудував дому свого і дому Господнього і стіни навколо Єрусалима.","Народ ще приносив жертви на висотах, бо не був побудований дім імені Господа до того часу.","І полюбив Соломон Господа, ходячи за уставом Давида, батька свого; але і він приносив жертви і куріння на висотах.","І пішов цар у Гаваон, щоб принести там жертву, бо там був головний жертовник. Тисячу всепалень підніс Соломон на тім жертовнику.","У Гаваоні явився Господь Соломону уві сні вночі, і сказав Бог: проси, що дати тобі.","І сказав Соломон: Ти зробив рабу Твоєму Давиду, батькові моєму, велику милість; і за те, що він ходив перед Тобою в істині і правді і з щирим серцем перед Тобою, Ти зберіг йому цю велику милість і дарував йому сина, який сидів би на престолі його, як це і є нині;","і нині, Господи Боже мій, Ти поставив раба Твого царем замість Давида, батька мого; але я отрок малий, не знаю ні мого виходу, ні входу;","і раб Твій — серед народу Твого, який обрав Ти, народу настільки численного, що за безліччю його не можна ні порахувати його, ні оглянути;","даруй же рабові Твоєму серце розумне, щоб судити народ Твій і розрізняти, що добро і що зло; бо хто може керувати цим численним народом Твоїм?","І благоугодно було Господу, що Соломон просив цього.","І сказав йому Бог: за те, що ти просив цього і не просив собі довгого життя, не просив собі багатства, не просив собі душ ворогів твоїх, але просив собі розуму, щоб уміти судити, —","ось, Я зроблю за словом твоїм: ось, Я даю тобі серце мудре і розумне, так що подібного до тебе не було раніше тебе, і після тебе не постане подібний до тебе;","і те, чого ти не просив, Я даю тобі, і багатство і славу, так що не буде подібного до тебе між царями в усі дні твої;","і якщо будеш ходити путями Моїми, зберігаючи устави Мої і заповіді Мої, як ходив батько твій Давид, Я продовжу і дні твої.","І пробудився Соломон, і ось, це було сновидіння. І пішов він в Єрусалим і став [перед жертовником] перед ковчегом завіту Господнього, і приніс всепалення і звершив жертви мирні, і зробив великий бенкет для всіх слуг своїх.","Тоді прийшли дві жінки блудниці до царя і стали перед ним.","І сказала одна жінка: о, господарю мій! я і ця жінка живемо в одному домі; і я народила при ній у цьому домі;","на третій день після того, як я народила, народила і ця жінка; і були ми разом, і в домі нікого стороннього з нами не було; тільки ми дві були в домі;","і помер син цієї жінки вночі, бо вона заспала його;","і встала вона вночі, і взяла сина мого від мене, коли я, раба твоя, спала, і поклала його до своїх грудей, а свого мертвого сина поклала до моїх грудей;","вранці я встала, щоб погодувати сина мого, і ось, він був мертвий; а коли я придивилася до нього вранці, то це був не мій син, якого я народила.","І сказала друга жінка: ні, мій син живий, а твій син мертвий. А та говорила їй: ні, твій син мертвий, а мій живий. І говорили вони так перед царем.","І сказав цар: ця говорить: мій син живий, а твій син мертвий; а та говорить: ні, твій син мертвий, а мій син живий.","І сказав цар: подайте мені меч. І принесли меч до царя.","І сказав цар: розсічіть живе дитя надвоє і віддайте половину одній і половину другій.","І відповіла та жінка, син якої був живий, царю, бо схвилювалося все нутро її від жалю до сина свого: о, господарю мій! віддайте їй цю дитину живу і не умертвляйте її. А інша говорила: нехай же не буде ні мені, ні тобі, рубайте.","І відповів цар і сказав: віддайте цій живе дитя, і не умертвляйте його: вона — його мати.","І почув весь Ізраїль про суд, як розсудив цар; і стали боятися царя, тому що побачили, що мудрість Божа в ньому, щоб чинити суд."],"x":{"1":"10.7.8","2":"2.17.4|13.33.17","4":"12.16.39|13.1.3","5":"13.1.7|10.9.2","6":"12.28.5|13.1.8|29.9.7","7":"32.10.23","8":"13.1.9","9":"29.6.21","12":"10.4.29","13":"29.7.11","14":"2.18.5|25.90.16|26.3.16","26":"31.49.15","27":"26.16.10","28":"29.8.4"}},{"v":["І був цар Соломон царем над усім Ізраїлем.","І ось начальники, які були в нього: Азарія, син Садока священика;","Елихореф і Ахия, сини Сиви, писарі; Іосафат, син Ахилуда, діловод;","Ванея, син Іодая, воєначальник; Садок і Авиафар — священики;","Азарія, син Нафана, начальник над приставниками, і Завуф, син Нафана священика — друг царя;","Ахисар –начальник над домом царським , і Адонірам, син Авди, — над податками.","І було у Соломона дванадцять приставників над усім Ізраїлем, і вони постачали продовольство цареві і дому його; кожен повинен був постачати продовольство на один місяць у рік.","Ось імена їхні: Бен-Хур — на горі Єфремовій;","Бен-Декер — у Макаці й у Шаалбимі, у Вефсамисі та в Елоні й у Беф-Ханані;","Бен-Хесед — в Арюбофі; йому ж належали Соко і вся земля Хефер;","Бен-Авинадав — над усім Нафаф-Дором; Тафаф, дочка Соломона, була його дружиною;","Ваана, син Ахилуда, у Фаанаху і Мегиддо і в усьому Беф-Сані, що біля Цартана нижче Ієзрееля, від Беф-Сана до Абел-Мехола, і навіть за Іокмеам;","Бен-Гевер — у Рамофі галаадському; у нього були селища Іаїра, сина Манассіїного, що в Галааді; у нього також область Аргов, що у Васані, шістдесят великих міст зі стінами і мідними засувами;","Ахинадав, син Гиддо, у Маханаїмі;","Ахимаас — у землі Неффалимовій; він узяв собі за дружину Васемафу, дочку Соломона;","Ваана, син Хушая, в землі Асировій і в Баалофі;","Іосафат, син Паруаха, у землі Іссахаровій;","Шимей, син Ели, у землі Веніаміновій;","Гевер, син Урія, в землі Галаадській, у землі Сигона, царя Аморрейського, і Ога, царя Васанського. Він був приставником у цій землі.","Іуда й Ізраїль, численні, як пісок біля моря, їли, пили і веселилися.","Соломон володів усіма царствами від ріки Євфрату до землі Филистимської і до меж Єгипту. Вони приносили дари і служили Соломону в усі дні життя його.","Продовольство Соломона на кожен день складали: тридцять ко́рів борошна пшеничного і шістдесят ко́рів іншого борошна,","десять волів відгодованих і двадцять волів з пасовища, і сто овець, крім оленів, і сарн, і сагайдаків, і відгодованих птахів;","бо він володарював над усією землею по цей бік ріки, від Типсаха до Гази, над усіма царями по цей бік ріки, і був у нього мир з усіма навколишніми країнами.","І жили Іуда й Ізраїль спокійно, кожен під виноградником своїм і під смоковницею своєю, від Дана до Вирсавії, в усі дні Соломона.","І було у Соломона сорок тисяч стійл для коней колісничних і дванадцять тисяч для кінноти.","І ті приставники постачали цареві Соломону все необхідне до столу царя, кожен у свій місяць, і не допускали недоліку ні в чому.","І ячмінь і солому для коней і для мулів постачали кожен у свою чергу на місце, де знаходився цар.","І дав Бог Соломону мудрість і дуже велике розуміння, і обширний розум, як пісок на березі моря.","І була мудрість Соломона вище за мудрість усіх синів сходу і всієї мудрости єгиптян.","Він був мудрішим за всіх людей, мудрішим і за Ефана езрахитянина, й Емана, і Халкола, і Дарди, синів Махола, й ім’я його було у славі в усіх навколишніх народів.","І вирік він три тисячі притч, і пісень його було тисяча і п’ять;","і говорив він про дерева, від кедра, що в Ливані, до ісопа, що виростає зі стіни; говорив і про тварин, і про птахів, і про плазунів, і про риб.","І приходили від усіх народів послухати мудрості Соломона, від усіх царів земних, які чули про мудрість його."],"x":{"1":"13.1.13","2":"12.6.9|9.8.17","3":"9.20.24","4":"10.2.27","5":"9.15.37","6":"10.5.14","9":"5.19.42-43","10":"5.12.17","11":"8.16.8|5.17.11","13":"4.4.43|12.2.23","14":"5.13.26","20":"12.29.22","21":"30.47.14|13.9.26","24":"11.15.16","25":"2.26.5","26":"4.17.16|10.10.26|13.1.14","29":"30.47.16","30":"54.7.22","31":"13.1.12|12.2.6|25.88.1","32":"26.1.1|27.12.11|28.1.1","34":"50.12.42|51.3.7|52.6.18"}},{"v":["І послав Хирам, цар Тирський, слуг своїх до Соломона, коли почув, що його помазали на царя на місце батька його; бо Хирам був другом Давида у все життя.","І послав також і Соломон до Хирама сказати:","ти знаєш, що Давид, батько мій, не міг побудувати дім імені Господа Бога свого через війни з навколишніми народами, доки Господь не підкорив їх під стопи ніг його;","нині ж Господь Бог мій дарував мені спокій звідусюди: немає супротивника і немає більше перепон;","і ось, я маю намір побудувати дім імені Господа Бога мого, як сказав Господь батькові моєму Давиду, говорячи: «син твій, якого Я посаджу замість тебе на престолі твоєму, він побудує дім імені Моєму»;","отже, накажи нарубати для мене кедрів Ливану; і ось, раби мої будуть разом із твоїми рабами, і я буду давати тобі плату за рабів твоїх, яку ти призначиш; бо ти знаєш, що в нас немає людей, які вміли б рубати дерева так, як сидоняни.","Коли почув Хирам слова Соломона, дуже зрадів і сказав: благословенний нині Господь, Який дав Давиду сина мудрого для управління цим численним народом!","І послав Хирам до Соломона сказати: я вислухав те, за чим ти посилав до мене, і виконаю все бажання твоє про дерева кедрові і дерева кипарисові;","раби мої звезуть їх з Ливану до моря, і я плотами доставлю їх морем до місця, яке ти призначиш мені, і там складу їх, і ти візьмеш; але і ти виконай моє бажання, щоб постачати хліб для мого дому.","І давав Хирам Соломону дерева кедрові і дерева кипарисові, цілком за його бажанням.","А Соломон давав Хираму двадцять тисяч ко́рів пшениці для споживання дому його і двадцять ко́рів оливкової вибитої олії: стільки давав Соломон Хираму щороку.","Господь дав мудрість Соломону, як обіцяв йому. І був мир між Хирамом і Соломоном, і вони уклали між собою союз.","І наклав цар Соломон повинність на весь Ізраїль; повинність же полягала в тридцяти тисячах чоловік.","І посилав їх на Ливан, по десять тисяч на місяць, поперемінно; місяць вони були на Ливані, а два місяці в домі своєму. Адонирам же начальствував над ними.","Ще у Соломона було сімдесят тисяч, що носять важкі речі, і вісімдесят тисяч каменосіків у горах,","крім трьох тисяч трьохсот начальників, поставлених Соломоном над роботою для нагляду за народом, що виконував роботу.","І повелів цар привозити камені великі, камені дорогі, для основи дому, камені оброблені.","Тесали ж їх робітники Соломонові і робітники Хирамові і гивлитяни, і готували дерева і камені для побудови дому [три роки]."],"x":{"2":"13.2.3","3":"12.28.3","4":"30.47.15","5":"9.7.13|10.6.12|12.22.10","6":"13.2.8","7":"10.10.9|13.2.12","8":"13.2.8|9.5.11","11":"13.2.10","12":"10.3.12","14":"10.4.6","15":"12.22.2|13.2.18","16":"13.2.18"}},{"v":["У чотириста вісімдесятому році після виходу синів Ізраїлевих із землі Єгипетської, у четвертий рік царювання Соломона над Ізраїлем, у місяці Зиф, який є другим місяцем, почав він будувати храм Господу.","Храм, який побудував цар Соломон Господу, довжиною був у шістдесят ліктів, шириною в двадцять і висотою в тридцять ліктів,","і притвор перед храмом у двадцять ліктів довжини, відповідно до ширини храму, і в десять ліктів ширини перед храмом.","І зробив він у домі вікна ґратчасті, глухі з відкосами.","І зробив прибудову навколо стін храму, навколо храму і давира*; і зробив бічні кімнати кругом.","Нижній ярус прибудови був шириною у п’ять ліктів, середній шириною у шість ліктів, а третій шириною у сім ліктів; бо навколо храму ззовні були зроблені уступи, щоб прибудова не доторкалася до стін храму.","Коли будувався храм, для будівництва використовувалися тесані камені; ні молота, ні тесла, ні всякого іншого залізного знаряддя не було чутно в храмі під час будівництва його.","Вхід у середній ярус був із правого боку храму. По круглих сходинках сходили в середній ярус , а від середнього — в третій.","І побудував він храм, і закінчив його, і обшив храм кедровими дошками.","І прибудував до всього храму бічні кімнати висотою в п’ять ліктів; вони прикріплені були до храму за допомогою кедрових колод.","І було слово Господа до Соломона, і сказано йому:","ось, ти будуєш храм; якщо ти будеш ходити за уставами Моїми, і чинити за визначеннями Моїми і дотримуватися всіх заповідей Моїх, керуючись ними, то Я виконаю на тобі слово Моє, яке Я сказав Давиду, батькові твоєму,","і буду жити серед синів Ізраїлевих, і не залишу народу Мого Ізраїля.","І побудував Соломон храм і скінчив його.","І обклав стіни храму всередині кедровими дошками; від підлоги храму до стелі всередині обклав деревом і покрив підлогу храму кипарисовими дошками.","І влаштував на задній стороні храму, за двадцять ліктів від краю, стіну, і обклав стіни і стелю кедровими дошками, і спорудив давир для Святого Святих.","Сорока ліктів був храм, тобто передня частина храму.","На кедрах всередині храму були вирізані подоби огірків і квітів, що розпускаються; усе було покрито кедром, каменю не було видно.","Давир же всередині храму він приготував для того, щоб поставити там ковчег завіту Господнього.","І давир був довжиною у двадцять ліктів, шириною у двадцять ліктів і висотою у двадцять ліктів; він обклав його чистим золотом; обклав також і кедровий жертовник.","І обклав Соломон храм усередині чистим золотом, і протягнув золоті ланцюги перед давиром, і обклав його золотом.","Весь храм він обклав золотом, весь храм до кінця, і весь жертовник, що перед давиром, обклав золотом.","І зробив у давирі двох херувимів з оливкового дерева, висотою у десять ліктів.","Одне крило херувима було у п’ять ліктів і друге крило херувима у п’ять ліктів; десять ліктів було від одного кінця крил його до другого кінця крил його.","У десять ліктів був і другий херувим; однакової міри й однакового вигляду були обидва херувими.","Висота одного херувима була десять ліктів, також і другого херувима.","І поставив він херувимів усередині внутрішньої частини храму. Крила ж херувимів були розпростерті, і доторкалося крило одного до однієї стіни, а крило другого херувима доторкалося до іншої стіни; інші ж крила їхні посеред храму сходилися крило з крилом.","І обклав він херувимів золотом.","І на всіх стінах храму навколо зробив різьблені зображення херувимів із пальмових дерев і квітів, що розпускаються, всередині і ззовні.","І підлогу у храмі обклав золотом у внутрішній і передній частині.","Для входу в давир зробив двері з оливкового дерева, з п’ятикутними одвірками.","На двох половинах дверей з оливкового дерева він зробив різьблених херувимів і пальми і квіти, що розпускаються, і обклав золотом; покрив золотом і херувимів і пальми.","І біля входу до храму зробив чотирикутні одвірки з оливкового дерева,","і двоє дверей з кипарисового дерева; обидві половинки одних дверей були рухомі, і обидві половинки других дверей були рухомі.","І вирізав на них херувимів і пальми і квіти, що розпускаються, і обклав золотом по різьбленню.","І побудував внутрішній двір із трьох рядів обтесаного каменю і з ряду кедрових брусів.","На четвертий рік, у місяці Зиф, [у місяці другому,] поклав він основи храму Господнього,","а на одинадцятому році, в місяці Булі, — це місяць восьмий, — він закінчив храм з усім приладдям його і за всіма кресленнями його; будував його сім років."],"x":{"1":"13.3.1|54.7.47","2":"13.3.3","3":"13.3.4|53.10.23|54.3.11","4":"36.40.16|36.41.16","5":"12.28.12","7":"10.5.18|56.2.5","8":"36.41.7:11","12":"9.7.8:12|10.5.5|12.22.10","13":"2.26.12|53.14.23","15":"13.3.5","16":"13.3.8","20":"13.3.8|10.7.48","23":"1.25.18|1.37.7","24":"13.3.11","29":"36.40.16","32":"36.11.18","34":"36.41.23","36":"13.4.9","38":"10.9.10|1.12.2|1.13.4"},"n":{"5":["Відділення для Святого Святих."]}},{"v":["А свій дім Соломон будував тринадцять років і закінчив увесь дім свій.","І побудував він дім з дерева ливанського, довжиною в сто ліктів, шириною у п’ятдесят ліктів, а висотою у тридцять ліктів, на чотирьох рядах кедрових стовпів; і кедрові колоди покладені були на стовпах.","І настелений був поміст із кедра над колодами на сорока п’яти стовпах, по п’ятнадцять у ряд.","Віконних луток було три ряди; і три ряди вікон , вікно навпроти вікна.","І всі двері й одвірки були чотирикутні, і вікно навпроти вікна, у три ряди.","І притвор із стовпів зробив він довжиною у п’ятдесят ліктів, шириною у тридцять ліктів, і перед ними ґанок, і стовпи, і поріг перед ними.","Ще притвор із престолом, з якого він судив, притвор для судилища зробив він і покрив усі підлоги кедром.","У домі, де він жив, інший двір позаду притвору був так само влаштований. І в домі дочки фараонової, яку взяв за себе Соломон, він зробив такий самий притвор.","Усе це зроблено було з дорогих каменів, обтесаних за розміром, обрізаних пилою, з внутрішнього і з зовнішнього боку, від підвалин до виступів, і з зовнішнього боку до великого двору.","І в основу покладені були камені дорогі, камені великі, камені в десять ліктів і камені у вісім ліктів,","і зверху дорогі камені, обтесані за розміром, і кедр.","Великий двір був обгороджений навколо трьома рядами тесаних каменів і одним рядом кедрових колод; так само і внутрішній двір храму Господнього і притвор храму.","І послав цар Соломон і взяв з Тира Хирама,","сина однієї вдови, з коліна Неффалимового. Батько його тирянин був мідник; він володів здатністю, мистецтвом і вмінням виробляти всякі речі з міді. І прийшов він до царя Соломона і виконував у нього всякі роботи:","і зробив він два мідних стовпи, кожен у вісімнадцять ліктів висотою, і шнур у дванадцять ліктів обіймав навкруги один і другий стовпи;","і два вінці, відлитих з міді, він зробив, щоб покласти наверху стовпів: п’ять ліктів висоти в одному вінці і п’ять ліктів висоти у другому вінці;","сітки плетеної роботи і шнури у вигляді ланцюжків для вінців, що були наверху стовпів: сім на одному вінці і сім на другому вінці.","Так зробив він стовпи і два ряди гранатових яблук навколо сітки, щоб покрити вінці, що наверху стовпів; те саме зробив і для другого вінця.","А в притворі вінці наверху стовпів зроблені на зразок лілеї, у чотири лікті,","і вінці на обох стовпах угорі, прямо над випуклістю, що поряд із сіткою; і на другому вінці, рядами навкруги, двісті гранатових яблук.","І поставив стовпи до притвору храму; поставив стовп на правому боці і дав йому ім’я Іахин, і поставив стовп на лівому боці і дав йому ім’я Воаз.","І над стовпами поставив вінці , зроблені на зразок лілеї; так закінчена робота над стовпами.","І зробив лите з міді море, — від краю його до краю його десять ліктів, — зовсім кругле, висотою у п’ять ліктів, і шнур у тридцять ліктів обіймав його навкруги.","Подоби огірків під краями його оточували його по десять на один лікоть, оточували море з усіх боків у два ряди; подоби огірків були відлиті з ним одним литтям.","Воно стояло на дванадцяти волах: три дивилися на північ, три дивилися на захід, три дивилися на південь і три дивилися на схід; море лежало на них, і зади їх повернені були усередину під нього.","Товщиною воно було в долоню, і краї його, зроблені подібно до країв чаші, були схожі на лілею, що розпустилася. Воно вміщало дві тисячі батів.","І зробив він десять мідних підстав; довжина кожної підстави — чотири лікті, ширина — чотири лікті і три лікті — висота.","І ось будова підстав: у них стінки, стінки між кутовими пластинами;","на стінках, що між кутами, були зображені леви, воли і херувими; також і на кутах, а вище і нижче левів і волів — розлогі вінки;","у кожної підстави по чотири мідних колеса й осі мідні. На чотирьох кутах виступи на зразок пліч, виступи литі внизу, під чашею, біля кожного вінка.","Отвір від внутрішнього вінка до верха в один лікоть; отвір його круглий, подібно до підніжжя стовпів, у півтора ліктя, і при отворі його статуї; але бічні стінки чотирикутні, не круглі.","Під стінками було чотири колеса, і вісі коліс на підставах; висота кожного колеса — півтора ліктя.","Будова коліс така сама, як будова коліс на колісниці; вісі їх, і ободи їх, і спиці їх, і ступиці їх, усе було лите.","Чотири виступи на чотирьох кутах кожної підстави; з підстави виходили виступи її.","І наверху підстави кругле підвищення на півліктя висоти; і наверху підстави руків’я її і стінки її з однієї з нею маси.","І відлив він на дощечках її руків’я і на стінках її херувимів, левів і пальми, скільки де дозволяло місце, і навколо розлогі вінки.","Так зробив він десять підстав: у всіх них одне лиття, одна міра, один вигляд.","І зробив десять мідних умивальниць: кожна умивальниця вміщала сорок батів, кожна умивальниця була в чотири лікті, кожна умивальниця стояла на одній з десяти підстав.","І розставив підстави — п’ять на правому боці храму і п’ять на лівому боці храму, а море поставив на правому боці храму, на східно-південній стороні.","І зробив Хирам умивальниці і лопатки і чаші. І закінчив Хирам усю роботу, яку виконував у царя Соломона для храму Господнього:","два стовпи і два опоясання вінців, що наверху стовпів, і дві сітки для покриття двох опоясань вінців, що наверху стовпів;","і чотириста ґранатових яблук на двох сітках; два ряди ґранатових яблук для кожної сітки, для покриття двох опоясань вінців, що на стовпах;","і десять підстав і десять умивальниць на підставах;","одне море і дванадцять волів під морем;","і тази, і лопатки, і чаші. Всі речі, що зробив Хирам царю Соломону для храму Господнього, були з полірованої міді.","Цар виливав їх у глинистій землі, в околиці Йордану, між Сокхофом і Цартаном.","І поставив Соломон усі ці речі на місце . Через надзвичайну їх кількість, вага міді не визначена.","І зробив Соломон усі речі, що у храмі Господньому: золотий жертовник і золотий стіл, на якому хліби предложення;","і світильники — п’ять праворуч і п’ять ліворуч, перед заднім відділенням храму, з чистого золота, і квіти, і лампадки, і щипці із золота;","і блюда, і ножі, і чаші, і лотки, і кадильниці з чистого золота, і завіси у дверях внутрішнього храму у Святому Святих і у дверях у храмі теж із золота.","Так звершена вся робота, яку виконав цар Соломон для храму Господнього. І приніс Соломон посвячене Давидом, батьком його; срібло і золото і речі віддав у скарбниці храму Господнього."],"x":{"1":"10.9.10","2":"10.10.17|31.22.8","7":"25.121.5","8":"10.3.1","9":"10.5.17","12":"10.6.36","13":"13.2.13","14":"13.2.14","15":"11.25.17","17":"13.3.16","21":"13.3.17","23":"13.4.2","25":"13.4.4","26":"13.4.5","27":"11.16.17|13.4.14","38":"13.4.6","40":"11.25.14|13.4.11","43":"10.7.27","46":"8.17.1|13.4.17","47":"13.4.18","49":"13.4.7:20","50":"11.12.13","51":"13.5.1"}},{"v":["Тоді скликав Соломон старійшин Ізраїлевих і всіх начальників колін, глав поколінь синів Ізраїлевих, до царя Соломона в Єрусалим, щоб перенести ковчег завіту Господнього з міста Давидового, тобто Сиона.","І зібралися до царя Соломона на свято всі ізраїльтяни в місяці Афанимі, який є сьомий місяць.","І прийшли усі старійшини Ізраїлеві; і підняли священики ковчег,","і понесли ковчег Господній і скинію зібрання і всі священні речі, що були в скинії; і несли їх священики і левити.","А цар Соломон і з ним уся громада Ізраїлева, яка зібралася до нього, йшли перед ковчегом, приносячи жертви з дрібної і великої худоби, яких неможливо порахувати і визначити, через велику кількість їх.","І внесли священики ковчег завіту Господнього на місце його, у давир храму, у Святе Святих, під крила херувимів.","Бо херувими простягали крила над місцем ковчега, і покривали херувими зверху ковчег і жердини його.","І висунулися жердини так, що головки жердини видні були зі святилища перед давиром, але не виходили назовні; вони там і до цього дня.","В ковчезі нічого не було, крім двох кам’яних скрижалей, які поклав туди Мойсей на Хориві, коли Господь уклав завіт із синами Ізраїлевими, після виходу їх із землі Єгипетської.","Коли священики вийшли зі святилища, хмара наповнила дім Господній;","і не могли священики стояти на служінні, через хмару, бо слава Господня наповнила храм Господній.","Тоді сказав Соломон: Господь сказав, що Він благоволить жити в імлі;","я побудував храм на оселю Твою, місце, щоб перебувати Тобі повіки.","І повернувся цар лицем своїм, і благословив усе зібрання ізраїльтян; все зібрання ізраїльтян стояло, —","і сказав: благословенний Господь Бог Ізраїлів, Який сказав Своїми вустами Давиду, батькові моєму, і нині виконав рукою Своєю! Він говорив:","«з того дня, як Я вивів народ Мій Ізраїля з Єгипту, Я не обрав міста в жодному з колін Ізраїлевих, щоб побудований був дім, у якому перебувало б ім’я Моє; [але обрав Єрусалим для перебування в ньому імені Мого] й обрав Давида, щоб бути йому над народом Моїм Ізраїлем».","У Давида, батька мого, було на серці побудувати храм імені Господа Бога Ізраїлевого;","але Господь сказав Давиду, батькові моєму: «у тебе є на серці побудувати храм імені Моєму; добре, що це в тебе лежить на серці;","однак не ти побудуєш храм, а син твій, який вийшов із стегон твоїх, він побудує храм імені Моєму».","І виконав Господь слово Своє, яке промовив. Я вступив на місце батька мого Давида і сів на престолі Ізраїлевім, як сказав Господь, і побудував храм імені Господа Бога Ізраїлевого;","і приготував там місце для ковчега, в якому завіт Господа, укладений Ним з батьками нашими, коли Він вивів їх із землі Єгипетської.","І став Соломон перед жертовником Господнім перед усім зібранням ізраїльтян, і підняв руки свої до неба,","і сказав: Господи Боже Ізраїлів! немає подібного до Тебе Бога на небесах вгорі і на землі внизу; Ти зберігаєш завіт і милість до рабів Твоїх, які ходять перед Тобою всім серцем своїм.","Ти виконав рабу Твоєму Давиду, батькові моєму, те, що говорив йому; що промовив Ти вустами Твоїми, те в цей день звершив рукою Твоєю.","І нині, Господи Боже Ізраїлів, виконай рабу Твоєму Давиду, батькові моєму, те, що говорив Ти йому, сказавши: «не припиниться у тебе перед лицем Моїм той, хто сидить на престолі Ізраїлевім, якщо тільки сини твої будуть триматися путі своєї, ходячи переді Мною так, як ти ходив переді Мною».","І нині, Боже Ізраїлів, нехай буде вірне слово Твоє, яке Ти промовив рабу Твоєму Давиду, батькові моєму!","Воістину, чи Богові жити на землі? Небо і небо небес не вміщають Тебе, тим менше цей храм, який я побудував [імені Твоєму];","але зглянься на молитву раба Твого і на прохання його, Господи Боже мій; почуй благання і молитву, якою раб Твій благає Тебе нині.","Нехай будуть очі Твої відкриті на храм цей день і ніч, на це місце, про яке Ти сказав: «Моє ім’я буде там»; почуй молитву, якою буде молитися раб Твій на місці цім.","Почуй моління раба Твого і народу Твого Ізраїля, коли вони будуть молитися на місці цьому; почуй на місці перебування Твого, на небесах, почуй і помилуй.","Коли хто згрішить проти ближнього свого, і вимагатиме від нього клятви, щоб він поклявся, і для клятви прийдуть до жертовника Твого у храм цей,","тоді Ти почуй з неба і вчини суд над рабами Твоїми, звинувать винного, поклавши вчинок його на голову його, і виправдай правого, воздавши йому за правдою його.","Коли народ Твій Ізраїль буде вражений ворогом за те, що згрішив перед Тобою, і коли вони звернуться до Тебе, і сповíдають ім’я Твоє, і будуть просити і благати Тебе в цьому храмі,","тоді Ти почуй з неба і прости гріх народу Твого Ізраїля, і поверни їх у землю, яку Ти дав батькам їхнім.","Коли закриється небо і не буде дощу за те, що вони згрішили перед Тобою, і коли помоляться на місці цьому і сповідають ім’я Твоє і навернуться від гріха свого, бо Ти смирив їх,","тоді почуй з неба і прости гріх рабів Твоїх і народу Твого Ізраїля, указавши їм добру путь, по якій іти, і пошли дощ на землю Твою, яку Ти дав народу Твоєму в спадщину.","Чи буде на землі голод, чи буде моровиця, чи буде палючий вітер, іржа, сарана, черва, чи ворог буде тіснити його на землі його, чи буде яка біда, яка хвороба, —","всяку молитву, всяке прохання, яке буде від якої-небудь людини у всьому народі Твоєму Ізраїлі, коли вони відчують біду в серці своєму і простягнуть руки свої до храму цього,","Ти почуй з неба, з місця оселі Твоєї, і помилуй; сотвори і воздай кожному за путями його, бо Ти знаєш серце його, тому що Ти один знаєш серця всіх синів людських:","щоб вони боялися Тебе в усі дні, доки живуть на землі, яку Ти дав батькам нашим.","Якщо й іноплемінник, що не від Твого народу Ізраїля, прийде з землі далекої заради імені Твого, —","бо і вони почують про Твоє ім’я велике і про Твою руку кріпку і про Твою силу простерту, — і прийде він і помолиться біля храму цього,","почуй з неба, з місця оселі Твоєї, і зроби все, про що буде взивати до Тебе іноплемінник, щоб усі народи землі знали ім’я Твоє, щоб боялися Тебе, як народ Твій Ізраїль, щоб знали, що ім’ям Твоїм називається храм цей, який я побудував.","Коли вийде народ Твій на війну проти ворога свого дорогою, якою Ти пошлеш його, і буде молитися Господу, обернувшись до міста, яке Ти обрав, і до храму, який я побудував імені Твоєму,","тоді почуй з неба молитву їхню і прохання їхнє і зроби, що потрібно для них.","Коли вони згрішать перед Тобою, — бо немає людини, яка не грішила б, — і Ти прогніваєшся на них і віддаси їх ворогам, і ті, що полонили їх, відведуть їх у ворожу землю, далеку або близьку;","і коли вони в землі, в якій будуть знаходитися в полоні, ввійдуть у себе і звернуться і будуть молитися Тобі в землі тих, хто полонив їх, промовляючи: «ми згрішили, вчинили беззаконня, ми винні»;","і коли звернуться до Тебе всім серцем своїм і всією душею своєю в землі ворогів, які полонили їх, і будуть молитися Тобі, звернувшись до землі своєї, яку Ти дав батькам їхнім, до міста, яке Ти обрав, і до храму, який я побудував імені Твоєму,","тоді почуй з неба, з місця оселі Твоєї, молитву і прохання їхні і вчини, що потрібно для них;","і прости народу Твоєму, в чому він згрішив перед Тобою, і всі провини його, які він зробив перед Тобою, і пробуди співстраждання до них у тих, хто полонив їх, щоб вони були милостиві до них:","бо вони Твій народ і Твій наділ, який Ти вивів з Єгипту, із залізної печі.","Нехай будуть [вуха Твої і] очі Твої відкриті на молитву раба Твого і на молитву народу Твого Ізраїля, щоб чути їх завжди, коли вони будуть закликати Тебе,","бо Ти відокремив їх Собі в наділ з усіх народів землі, як Ти вирік через Мойсея, раба Твого, коли вивів батьків наших з Єгипту, Владико Господи!","Коли Соломон промовив усі ці моління і прохання до Господа, тоді встав з колін від жертовника Господнього, руки ж його були підняті до неба.","І стоячи благословив усе зібрання ізраїльтян, гучним голосом промовляючи:","благословенний Господь [Бог], Який дав спокій народу Своєму Ізраїлю, як говорив! не залишилося невиконаним жодне слово з усіх благих слів Його, які Він вирік через раба Свого Мойсея;","нехай буде з нами Господь Бог наш, як був Він з батьками нашими, нехай не залишить нас, нехай не покине нас,","схиляючи до Себе серця наші, щоб ми ходили всіма путями Його і дотримувалися заповідей Його й уставів Його і законів Його, які Він заповів батькам нашим;","і нехай будуть слова ці, якими я молився [нині] перед Господом, близькі до Господа Бога нашого день і ніч, щоб Він робив, що потрібно для раба Свого, і що потрібно для народу Свого Ізраїля, з дня у день,","щоб усі народи пізнали, що Господь є Бог і немає, крім Нього;","нехай буде серце ваше цілком віддане Господу Богу нашому, щоб ходити за уставами Його і дотримуватися заповідей Його, як нині.","І цар і всі ізраїльтяни з ним принесли жертву Господу.","І приніс Соломон у мирну жертву, яку приніс він Господу, двадцять дві тисячі великої худоби і сто двадцять тисяч дрібної худоби. Так освятили храм Господу цар і всі сини Ізраїлеві.","У той же день освятив цар середню частину двору, що перед храмом Господнім, зробивши там всепалення і хлібне приношення і вознісши жир мирних жертв, тому що мідний жертовник, який перед Господом, був малий для розміщення всепалення і хлібного приношення і жиру мирних жертв.","І зробив Соломон у цей час свято, і весь Ізраїль з ним, — велике зібрання, яке зійшлося від входу в Емаф до ріки Єгипетської перед Господом Богом нашим; [і їли, і пили, і молилися перед Господом Богом нашим біля побудованого храму] — сім днів і ще сім днів, чотирнадцять днів.","У восьмий день Соломон відпустив народ. І благословили царя і пішли в намети свої, радіючи і веселячись у серці за все добро, яке зробив Господь рабові Своєму Давиду і народові Своєму Ізраїлю."],"x":{"1":"13.5.2","2":"2.23.34|4.16.13|13.7.9","3":"3.4.15","4":"13.5.5","5":"13.5.6","6":"13.5.7|1.25.18","9":"4.10.5|75.9.4","10":"1.40.34","11":"1.16.10","12":"13.6.1","14":"13.6.3","16":"11.21.4|13.6.5-6","17":"13.7.2","19":"9.7.5","20":"9.7.12","22":"13.6.12|22.2.8","24":"13.6.15","25":"9.7.12:16","26":"9.7.28","27":"13.6.18|31.66.1|32.23.24","29":"4.12.11|10.9.3|11.21.4","30":"16.7.38","31":"13.6.22","32":"13.6.23|4.25.1|36.9.10","33":"13.6.24|37.9.7","35":"4.11.17|13.6.26","36":"13.6.27|25.85.11|26.9.6","37":"2.26.16","39":"8.16.7|13.6.30|25.7.10","41":"13.6.32|54.8.27|4.3.24","43":"31.56.7|50.21.13","44":"13.6.34|37.6.10","45":"13.6.35","46":"27.7.20|58.1.8|26.20.9|16.8.35","48":"4.30.2|13.6.37|36.8.16","50":"17.2.2|26.16.7|32.42.12","51":"4.4.20","52":"13.6.40|25.120.4","53":"1.19.5","54":"13.7.1","56":"4.12.10|5.21.45|5.23.14","57":"25.9.11","58":"25.118.112|25.140.4","59":"25.147.8","60":"31.41.4|31.43.10|32.3.23","62":"13.7.4","63":"13.7.5","64":"13.4.1","65":"13.7.8|3.34.5:8|2.23.34","66":"13.7.10"}},{"v":["Після того, як Соломон скінчив будівництво храму Господнього і дому царського й усе, що Соломон бажав зробити,","явився Соломону Господь удруге, як явився йому в Гаваоні.","І сказав йому Господь: Я почув молитву твою і прохання твоє, про що ти просив Мене; [зробив усе за молитвою твоєю]. Я освятив цей храм, який ти побудував, щоб перебувати імені Моєму там повік; і будуть очі Мої і серце Моє там в усі дні.","І якщо ти будеш ходити перед лицем Моїм, як ходив батько твій Давид, у чистоті серця й у правоті, виконуючи все, що Я заповів тобі, і якщо будеш зберігати устави Мої і закони Мої,","то Я поставлю царський престіл твій над Ізраїлем повік, як Я сказав батькові твоєму Давиду, говорячи: «не припиниться в тебе той, хто сидить на престолі Ізраїлевім».","Якщо ж ви і сини ваші відступите від Мене і не будете дотримуватися заповідей Моїх і уставів Моїх, які Я дав вам, і підете і станете служити іншим богам і поклонятися їм,","то Я знищу Ізраїля з лиця землі, яку Я дав йому, і храм, який Я освятив імені Моєму, відкину від лиця Мого, і буде Ізраїль притчею і посміховиськом у всіх народів.","І про храм цей високий усякий, хто проходитиме мимо нього, вжахнеться і свисне, і скаже: «за що Господь зробив так із цією землею і з цим храмом?»","І скажуть: «за те, що вони залишили Господа Бога свого, Який вивів батьків їхніх із землі Єгипетської, і прийняли інших богів, і поклонялися їм і служили їм, — за це навів на них Господь усю цю біду».","Після закінчення двадцяти років, за які Соломон побудував два будинки, — дім Господній і дім царський, —","на що Хирам, цар Тирський, постачав Соломону дерева кедрові і дерева кипарисові і золото, за його бажанням, — цар Соломон дав Хираму двадцять міст у землі Галилейській.","І вийшов Хирам з Тира подивитися міста, які дав йому Соломон, і вони не сподобалися йому.","І сказав він: що це за міста, які ти, брате мій, дав мені? І назвав їх землею Кавул, як називаються вони до сьогодні.","І послав Хирам царю сто двадцять талантів золота.","Ось розпорядження про податки, які наклав цар Соломон, щоб побудувати храм Господній і дім свій, і Милло, і стіну єрусалимську, Гацор, і Мегиддо, і Газер.","Фараон, цар Єгипетський, прийшов і взяв Газер, і спалив його вогнем, і хананеїв, які жили в місті, повбивав, і віддав його в посаг дочці своїй, дружині Соломоновій.","І побудував Соломон Газер і нижній Бефорон,","і Ваалаф і Фадмор у пустелі,","і всі міста для запасів, які були у Соломона, і міста для колісниць, і міста для кінноти і все те, що Соломон хотів побудувати в Єрусалимі і на Ливані й у всій землі свого володіння.","Весь народ, який залишився від аморреїв, хеттеїв, ферезеїв, [хананеїв,] евеїв, ієвусеїв і [гергесеїв], які були не із синів Ізраїлевих,","дітей їхніх, що залишилися після них на землі, яких сини Ізраїлеві не могли знищити, Соломон зробив оброчними робітниками до цього дня.","Синів же Ізраїлевих Соломон не робив робітниками, але вони були його воїнами, його слугами, його вельможами, його воєначальниками і вождями його колісниць і його вершників.","Ось головні приставники над роботами Соломоновими: тих, що управляли народом, який виконував роботи, було п’ятсот п’ятдесят.","Дочка фараонова перейшла з міста Давидового у свій дім, який побудував для неї Соломон; потім побудував він Милло.","І приносив Соломон три рази на рік всепалення і мирні жертви на жертовнику, який він побудував Господу, і куріння на ньому звершував перед Господом. І закінчив він будівництво дому.","Цар Соломон також зробив корабель в Ецион-Гавері, що при Елафі, на березі Червоного моря, в землі Ідумейській.","І послав Хирам на кораблі своїх підданих корабельників, які знають море, з підданими Соломоновими;","і вирушили вони в Офир, і взяли звідти золота чотириста двадцять талантів, і привезли цареві Соломону."],"x":{"1":"13.7.11","2":"10.3.5","3":"4.12.11|10.8.29|11.21.4:7","5":"10.6.12|9.7.12","8":"4.29.24|32.22.8","10":"10.7.1|13.8.1","15":"11.12.20|10.11.27|5.10.33|5.11.10","16":"5.16.10","17":"5.18.13|13.8.5","18":"5.19.8|13.8.6","20":"13.8.7","21":"5.16.10|13.8.8","22":"2.25.39|13.8.9","23":"13.8.10","24":"13.8.11","25":"1.23.14|13.8.12-13","26":"4.2.8|13.8.17","28":"10.22.48|13.3.6"}},{"v":["Цариця Савська, почувши про славу Соломона в ім’я Господа, прийшла випробувати його загадками.","І прийшла вона в Єрусалим з дуже великим багатством: верблюди нав’ючені були пахощами і великою кількістю золота і коштовного каміння; і прийшла до Соломона і розмовляла з ним про все, що було у неї на серці.","І пояснив їй Соломон усі слова її, і не було нічого невідомого царю, чого він не пояснив би їй.","І побачила цариця Савська всю мудрість Соломона і дім, який він побудував,","і їжу за столом його, і житло рабів його, і стрункість слуг його, і одяг їхній, і виночерпіїв його, і всепалення його, які він приносив у храмі Господньому. І не могла вона більше утриматися","і сказала цареві: правда те, що я чула в землі своїй про діла твої і про мудрість твою;","але я не вірила словам, доки не прийшла, і не побачила очима моїми: і ось, мені й половини не сказано; мудрости і багатства в тебе більше, ніж як я чула.","Блаженні люди твої і блаженні ці слуги твої, які завжди стоять перед тобою і чують мудрість твою!","Нехай буде благословенний Господь Бог твій, Який благоволив посадити тебе на престіл Ізраїлів! Господь, з вічної любови Своєї до Ізраїля, поставив тебе царем, чинити суд і правду.","І подарувала вона царю сто двадцять талантів золота і велику кількість пахощів і коштовне каміння; ніколи ще не приходило такої великої кількості пахощів, як подарувала цариця Савська царю Соломону.","І корабель Хирамів, який привозив золото з Офира, привіз з Офира велику кількість червоного дерева і коштовних каменів.","І зробив цар з цього червоного дерева поручні для храму Господнього і для дому царського, і гуслі і псалтирі для співців; ніколи не приходило стільки червоного дерева і не бачено було до цього дня.","І цар Соломон дав цариці Савській усе, чого вона бажала і чого просила, зверх того, що подарував їй цар Соломон своїми руками. І вирушила вона назад у свою землю, вона й усі слуги її.","Вага золота, що надходило Соломону щороку, була шістсот шістдесят шість талантів золотих,","зверх того, що отримувалося від рознощиків товару і від торгівлі купців, і від усіх царів аравійських і від обласних начальників.","І зробив цар Соломон двісті великих щитів з кованого золота, по шістсот сиклів пішло на кожен щит;","і триста менших щитів з кованого золота, по три міни золота пішло на кожен щит; і поставив їх цар у домі з ливанського дерева.","І зробив цар великий престіл зі слонової кості й обклав його чистим золотом;","до престолу було шість сходинок; верх позаду престолу був круглий, і були з обох боків у місцях сидіння підлокітники, і два леви стояли біля підлокітників;","і ще дванадцять левів стояли там на шести сходинках з обох боків. Подібного до цього не було в жодному царстві.","І весь посуд для пиття у царя Соломона був золотий, і весь посуд в домі з ливанського дерева був з чистого золота; зі срібла нічого не було, тому що срібло в дні Соломона вважалося нічим;","бо у царя був на морі фарсиський корабель з кораблем Хирамовим; один раз на три роки приходив фарсиський корабель, який привозив золото і срібло, і слонову кістку, і мавп, і павичів.","Цар Соломон перевершував усіх царів землі багатством і мудрістю.","І всі [царі] на землі хотіли бачити Соломона, щоб послухати мудрість його, яку Бог вклав у серце його.","І вони підносили йому, кожен від себе, в дар: сосуди срібні і сосуди золоті, і одяг, і зброю, і пахощі, коней і мулів, щороку.","І набрав Соломон колісниць і вершників; у нього було тисяча чотириста колісниць* і дванадцять тисяч вершників; і розмістив він їх по колісничних містах і при царі в Єрусалимі. [І панував він над усіма морями від ріки до землі Филистимської і до меж Єгипту.]","І зробив цар срібло в Єрусалимі рівноцінним із простими каменями, а кедри, через їх безліч, зробив рівноцінними із сикоморами, що ростуть на низинних місцях.","Коней же царю Соломону приводили з Єгипту і з Куви; царські купці купували їх з Куви за гроші.","Колісницю з Єгипту одержували і доставляли за шістсот сиклів срібла, а коня за сто п’ятдесят. У такий же спосіб вони руками своїми доставляли все це царям хеттейським і царям арамейським."],"x":{"1":"13.9.1|50.12.42|52.11.31","3":"13.9.2","4":"13.9.3","6":"13.9.5","8":"13.9.7|52.2.47|76.7.15","10":"13.9.9","12":"27.2.8","13":"13.9.12","14":"13.9.13","16":"10.14.26","17":"32.46.3","18":"13.9.17","21":"13.9.20","22":"10.9.27|13.9.21","23":"10.3.12|13.1.1","26":"13.1.14","27":"13.1.15","28":"4.17.16|13.1.16"},"n":{"26":["У грецькому перекладі: сорок тисяч коней колісничних."]}},{"v":["І полюбив цар Соломон багато чужоземних жінок, крім дочки фараонової, моавитянок, аммонитянок, ідумеянок, сидонянок, хеттеянок,","з тих народів, про які Господь сказав синам Ізраїлевим: «не входьте до них, і вони нехай не входять до вас, щоб вони не схилили серця вашого до своїх богів»; до них приліпився Соломон любов’ю.","І було в нього сімсот дружин і триста наложниць; і розбестили дружини його серце його.","В часи старости Соломона дружини його схилили серце його до інших богів, і серце його не було цілком віддане Господу Богу своєму, як серце Давида, батька його.","І став Соломон служити Астарті, божеству сидонському, і Милхому, мерзоті аммонитській.","І робив Соломон неугодне перед очима Господа і не цілком ішов за Господом, як Давид, батько його.","Тоді побудував Соломон капище Хамосу, мерзоті моавитській, на горі, що перед Єрусалимом, і Молохові, мерзоті аммонитській.","Так зробив він для всіх своїх чужоземних дружин, які кадили і приносили жертви своїм богам.","І розгнівався Господь на Соломона за те, що він відхилив серце своє від Господа Бога Ізраїлевого, Який двічі являвся йому,","і заповів йому, щоб він не тримався інших богів; але він не виконав того, що заповів йому Господь [Бог].","І сказав Господь Соломону: за те, що так у тебе робиться, і ти не зберіг завіту Мого й уставів Моїх, які Я заповів тобі, Я відторгну від тебе царство і віддам його рабові твоєму;","але в дні твої Я не зроблю цього заради Давида, батька твого; від руки сина твого відніму його;","і не все царство відніму; одне коліно дам синові твоєму заради Давида, раба Мого, і заради Єрусалима, який Я обрав.","І підняв Господь супротивника на Соломона, Адера ідумеянина, з царського Ідумейського роду.","Коли Давид був у Ідумеї, і воєначальник Іоав прийшов для поховання убитих і побив усю чоловічу стать в Ідумеї, —","бо шість місяців прожили там Іоав і всі ізраїльтяни, доки не знищили всю чоловічу стать в Ідумеї, —","тоді цей Адер утік у Єгипет і з ним кілька ідумеян, що служили при батькові його; Адер був тоді малою дитиною.","Вирушивши з Мадиама, вони прийшли у Фаран і взяли з собою людей з Фарана і прийшли в Єгипет до фараона, царя Єгипетського. [Адер увійшов до фараона, і] він дав йому дім, і призначив йому утримання, і дав йому землю.","Адер здобув у фараона велику милість, так що він дав йому за дружину сестру своєї дружини, сестру цариці Тахпенеси.","І народила йому сестра Тахпенеси сина Генувата. Тахпенеса виховувала його в домі фараоновім; і жив Генуват у домі фараона разом із синами фараоновими.","Коли Адер почув, що Давид спочив з батьками своїми і що воєначальник Іоав помер, то сказав фараонові: відпусти мене, я піду у свою землю.","І сказав йому фараон: хіба ти маєш потребу в чомусь у мене, що хочеш іти у свою землю? Він відповів: ні, але відпусти мене. [І повернувся Адер у землю свою.]","І підняв Бог проти Соломона ще супротивника, Разона, сина Елиади, який утік від господаря свого Адраазара, царя Сувського,","і, зібравши біля себе людей, зробився начальником зграї, після того, як Давид розбив Адраазара ; і пішли вони в Дамаск, і оселилися там, і володарювали в Дамаску.","І був він супротивником Ізраїлю в усі дні Соломона. Крім зла, заподіяного Адером, він завжди шкодив Ізраїлю і став царем Сирії.","І Ієровоам, син Наватів, єфремлянин з Цареди, — ім’я матері його вдови: Церуа, — раб Соломонів, підняв руку на царя.","І ось обставина, за якої він підняв руку на царя: Соломон будував Милло, лагодив пошкодження в місті Давида, батька свого.","Ієровоам був чоловіком мужнім. Соломон, помітивши, що цей молодий чоловік вміє робити справу, поставив його наглядачем над оброчними з дому Йосифового.","У той час трапилося Ієровоаму вийти з Єрусалима; і зустрів його на дорозі пророк Ахия силомлянин, і на ньому був новий одяг. На полі їх було тільки двоє.","І взяв Ахия новий одяг, який був на ньому, і роздер його на дванадцять частин,","і сказав Ієровоаму: візьми собі десять частин, тому що так говорить Господь Бог Ізраїлів: ось, Я відторгаю царство з руки Соломонової і даю тобі десять колін,","а одне коліно* залишиться за ним заради раба Мого Давида і заради міста Єрусалима, яке Я обрав з усіх колін Ізраїлевих.","Це за те, що вони залишили Мене і стали поклонятися Астарті, божеству сидонському, і Хамосу, богу моавитському, і Милхому, богу аммонитському, і не пішли путями Моїми, щоб робити угодне перед очима Моїми і дотримуватися уставів Моїх і заповідей Моїх, подібно до Давида, батька його.","Я не беру всього царства з руки його, але Я залишаю його владикою на всі дні життя його заради Давида, раба Мого, якого Я обрав, який дотримувався заповідей Моїх і уставів Моїх;","але візьму царство з руки сина його і дам тобі з нього десять колін;","а синові його дам одне коліно, щоб залишався світильник Давида, раба Мого, в усі дні перед лицем Моїм, у місті Єрусалимі, яке Я обрав Собі для перебування там імені Мого.","Тебе Я обираю, і ти будеш володарювати над усім, чого побажає душа твоя, і будеш царем над Ізраїлем;","і якщо будеш дотримуватися всього, що Я заповідаю тобі, і будеш ходити путями Моїми і робити угодне перед очима Моїми, дотримуючись уставів Моїх і заповідей Моїх, як робив раб Мій Давид, то Я буду з тобою й зроблю твій дім міцним, як Я зробив Давиду, і віддам тобі Ізраїля;","і смирю Я рід Давидів за це, але не на всі дні.","Соломон же хотів умертвити Ієровоама; але Ієровоам встав і втік у Єгипет до Сусакима, царя Єгипетського, і жив у Єгипті до смерті Соломонової.","Інші події Соломонові й усе, що він робив, і мудрість його описані в книзі діл Соломонових.","Царював Соломон в Єрусалимі над усім Ізраїлем сорок років.","І спочив Соломон з батьками своїми і похований був у місті Давида, батька свого, і став царем замість нього син його Ровоам."],"x":{"1":"4.17.17","2":"1.34.15-16|4.7.3","4":"10.21.25|30.47.22","5":"6.2.13|11.23.13","7":"3.21.29|11.23.13","9":"10.9.2","10":"10.6.12","11":"10.12.15","12":"10.12.16","13":"10.9.3","15":"9.8.14","16":"9.8.13","17":"10.22.47|9.8.14","18":"0.14.6|0.25.2|0.36.35","21":"10.2.10|1.4.18","23":"9.8.3","24":"9.8.3","26":"13.13.6","27":"10.9.15","30":"10.12.15|11.17.21","31":"10.12.15","32":"10.12.20","34":"9.7.18|25.88.4-5|30.47.24","36":"10.12.15-16|9.21.17","38":"8.2.35|9.7.16|10.9.4","39":"52.1.32-33","40":"10.14.30","41":"13.1.1|30.47.23","43":"13.9.31|50.1.7"},"n":{"32":["У грецькому перекладі: два коліна."]}},{"v":["І пішов Ровоам у Сихем, бо в Сихем прийшли всі ізраїльтяни, щоб поставити його царем.","І почув про те Ієровоам, син Наватів, коли перебував ще в Єгипті, куди втік від царя Соломона, і повернувся Ієровоам з Єгипту;","і послали за ним і покликали його. Тоді Ієровоам і все зібрання ізраїльтян прийшли і говорили [цареві] Ровоаму і сказали:","батько твій наклав на нас тяжке ярмо, ти ж полегши нам жорстоку роботу батька твого і тяжке ярмо, яке він наклав на нас, і тоді ми будемо служити тобі.","І сказав він їм: підіть і через три дні знову прийдіть до мене. І пішов народ.","Цар Ровоам радився зі старцями, які стояли перед Соломоном, батьком його, за життя його, і говорив: як порадите ви мені відповісти цьому народу?","Вони говорили йому і сказали: якщо ти в цей день будеш слугою народу цього і будеш слугувати йому, і задовольниш їх і будеш говорити з ними ласкаво, то вони будуть твоїми рабами на всі дні.","Але він зневажив пораду старців, що вони радили йому, і радився з молодими людьми, які виросли разом з ним і які стояли перед ним,","і сказав їм: що ви порадите мені відповісти народу цьому, який говорив мені і сказав: «полегши ярмо, яке наклав на нас батько твій»?","І говорили йому молоді люди, які виросли разом з ним, і сказали: так скажи народу цьому, який говорив тобі і сказав: «батько твій наклав на нас тяжке ярмо, ти ж полегши нам»; так скажи їм: «мій мізинець товщий за стегна батька мого;","отже, якщо батько мій обтяжував вас тяжким ярмом, то я збільшу ярмо ваше; батько мій карав вас бичами, а я буду карати вас скорпіонами».","Ієровоам і весь народ прийшли до Ровоама на третій день, як наказав цар, сказавши: прийдіть до мене на третій день.","І відповідав цар народу суворо і зневажив пораду старців, що вони радили йому;","і говорив він за порадою молодих людей і сказав: батько мій наклав на вас тяжке ярмо, а я збільшу ярмо ваше; батько мій карав вас бичами, а я буду карати вас скорпіонами.","І не послухав цар народу, бо так суджено було Господом, щоб сповнилося слово Його, яке прорік Господь через Ахию силомлянина Ієровоаму, синові Наватовому.","І побачили всі ізраїльтяни, що цар не послухав їх. І відповів народ цареві і сказав: яка нам частина в Давиді? немає нам частки в сині Ієссеєвому; по наметах своїх, Ізраїль! тепер знай свій дім, Давиде! І розійшовся Ізраїль по наметах своїх.","Тільки над синами Ізраїлевими, які жили в містах Іудиних, царював Ровоам.","І послав цар Ровоам Адонирама, начальника над податками; але всі ізраїльтяни закидали його камінням, і він помер; цар же Ровоам поспішно зійшов на колісницю, щоб утекти в Єрусалим.","І відокремився Ізраїль від дому Давидового до цього дня.","Коли почули всі ізраїльтяни, що Ієровоам повернувся [з Єгипту], то послали і прикликали його на зібрання, і поставили його царем над усіма ізраїльтянами. За домом Давидовим не залишилося нікого, крім коліна Іудиного [і Веніамінового].","Ровоам, прибувши в Єрусалим, зібрав з усього дому Іудиного і з коліна Веніамінового сто вісімдесят тисяч добірних воїнів, щоб воювати з домом Ізраїлевим для того, щоб повернути царство Ровоаму, синові Соломона.","І було слово Боже до Самея, чоловіка Божого, і сказано:","скажи Ровоаму, синові Соломона, цареві Юдейському, і всьому дому Іудиному і Веніаміновому й іншому народу:","так говорить Господь: не ходіть і не починайте війни з братами вашими, синами Ізраїлевими; поверніться кожен у дім свій, бо від Мене це було. І послухалися вони слова Господнього і пішли назад за словом Господа.","І оббудував Ієровоам Сихем на горі Єфремовій й оселився в ньому; звідти пішов і побудував Пенуїл.","І говорив Ієровоам у серці своєму: царство може знову перейти до дому Давидового;","якщо народ цей буде ходити в Єрусалим для жертвоприношення в домі Господньому, то серце народу цього навернеться до господаря свого, до Ровоама, царя Юдейського, і уб’ють вони мене і повернуться до Ровоама, царя Юдейського.","І порадившись, цар зробив двох золотих тельців і сказав [народу]: не потрібно вам ходити в Єрусалим; ось боги твої, Ізраїль, які вивели тебе з землі Єгипетської.","І поставив одного у Вефилі, а іншого в Дані.","І привело це до гріха, бо народ став ходити до одного з них , навіть у Дан, [і залишили храм Господній].","І побудував він капище на висоті і поставив з народу священиків, які не були із синів Левіїних.","І встановив Ієровоам свято у восьмий місяць, у п’ятнадцятий день місяця, подібне до того свята, яке було в Юдеї, і приносив жертви на жертовнику; те саме зробив він у Вефилі, щоб приносити жертву тельцям, яких зробив. І поставив у Вефилі священиків висот, які спорудив,","і приніс жертви на жертовнику, який він зробив у Вефилі, у п’ятнадцятий день восьмого місяця, місяця, який він довільно призначив; і встановив свято для синів Ізраїлевих, і підійшов до жертовника, щоб зробити куріння."],"x":{"1":"13.10.1","2":"13.10.2|10.11.40","5":"13.10.5","6":"13.10.6","7":"13.10.7|30.37.18","8":"13.10.8|30.26.26|30.47.28","10":"13.10.10","11":"13.10.11","12":"13.10.12","15":"10.11.31","16":"13.10.16","17":"10.11.32","18":"9.20.24|10.4.6","19":"11.17.21","20":"10.11.11:32","21":"13.11.1","22":"13.11.2","24":"10.12.15","25":"6.8.17|6.9.45|10.12.1","28":"1.32.8|11.17.16","29":"32.48.13","31":"13.11.15","32":"38.7.5","33":"40.3.14|62.1.25"}},{"v":["І ось, чоловік Божий прийшов з Юдеї за словом Господнім у Вефиль, в той час, коли Ієровоам стояв біля жертовника, щоб звершити куріння.","І промовив до жертовника слово Господнє і сказав: жертовник, жертовник! так говорить Господь: ось, народиться син дому Давидовому, ім’я йому Іосія, і принесе на тобі в жертву священиків висот, які звершують на тобі куріння, і людські кістки спалить на тобі.","І дав у той день знамення, сказавши: ось знамення того, що це прорік Господь: ось, цей жертовник розпадеться, і попіл, що на ньому, розсипеться.","Коли цар почув слово чоловіка Божого, промовлене до жертовника у Вефилі, то простягнув Ієровоам руку свою від жертовника, говорячи: візьміть його. І одерев’яніла рука його, яку він простягнув на нього, і не міг він повернути її до себе.","І жертовник розпався, і попіл з жертовника розсипався, за знаменням, яке дав чоловік Божий словом Господнім.","І сказав цар [Ієровоам] чоловіку Божому: умилостив лице Господа Бога твого і помолися за мене, щоб рука моя могла повернутися до мене. Й умилостивив чоловік Божий лице Господа, і рука царя повернулася до нього і стала, як раніше.","І сказав цар чоловіку Божому: зайди зі мною в дім і підкріпи себе їжею, і я дам тобі подарунок.","Але чоловік Божий сказав цареві: хоч би ти давав мені половину дому твого, я не піду з тобою і не буду їсти хліба і не буду пити води в цьому місці,","бо так заповідано мені словом Господнім: «не їж там хліба і не пий води і не повертайся тією дорогою, якою ти йшов».","І пішов він іншою дорогою і не пішов назад тією дорогою, якою прийшов у Вефиль.","У Вефилі жив один пророк-старець. Син його прийшов і розповів йому все, що зробив сьогодні чоловік Божий у Вефилі; і слова, які він говорив цареві, переказали сини батькові своєму.","І запитав їх батько їхній: якою дорогою він пішов? І показали сини його, якою дорогою пішов чоловік Божий, який приходив з Юдеї.","І сказав він синам своїм: осідлайте мені осла. І осідлали йому осла, і він сів на нього.","І поїхав за чоловіком Божим, і знайшов його, що сидів під дубом, і сказав йому: чи ти чоловік Божий, який прийшов з Юдеї? І сказав той: я.","І сказав йому: зайди до мене в дім і поїж хліба.","Той сказав: я не можу повернутися з тобою і піти до тебе; не буду їсти хліба і не буду пити в тебе води в цьому місці,","бо словом Господнім сказано мені: «не їж хліба і не пий там води, і не повертайся тією дорогою, якою ти йшов».","І сказав він йому: і я пророк такий самий, як ти, і ангел говорив мені словом Господнім, і сказав: «поверни його до себе в дім; нехай поїсть він хліба і нап’ється води». — Він сказав неправду йому.","І той повернувся з ним, і поїв хліба в його домі, і напився води.","Коли вони ще сиділи за столом, слово Господнє було до пророка, який повернув його.","І промовив він до чоловіка Божого, який прийшов з Юдеї, і сказав: так говорить Господь: за те, що ти не підкорився вустам Господа і не дотримав повеління, яке заповів тобі Господь Бог твій,","але повернувся, їв хліб і пив воду в тому місці, про яке Він сказав тобі: «не їж хліба і не пий води», тіло твоє не ввійде у гробницю батьків твоїх.","Після того, як той поїв хліба і напився, він осідлав осла для пророка, якого він повернув.","І вирушив той. І зустрів його на дорозі лев і умертвив його. І лежало тіло його, кинуте на дорозі; осел же стояв біля нього, і лев стояв біля тіла.","І ось, люди, які проходили мимо, побачили тіло, кинуте на дорозі, і лева, що стоїть біля тіла, і пішли і розповіли в місті, в якому жив пророк-старець.","Пророк, який повернув його з дороги, почувши це , сказав: це той чоловік Божий, який не підкорився вустам Господа; Господь віддав його леву, який роздер його й умертвив його, за словом Господа, яке Він прорік йому.","І сказав синам своїм: осідлайте мені осла. І осідлали вони.","Він вирушив і знайшов тіло його, кинуте на дорозі; осел же і лев стояли біля тіла; лев не з’їв тіла і не роздер осла.","І підняв пророк тіло чоловіка Божого, і поклав його на осла, і повіз його назад. І пішов пророк-старець у місто своє , щоб оплакати і поховати його.","І поклав тіло його у своїй гробниці і плакав за ним: жаль, брате мій!","Після поховання його він сказав синам своїм: коли я помру, поховаєте мене в гробниці, в якій похований чоловік Божий; біля кісток його покладете кістки мої;","бо збудеться слово, яке він за велінням Господнім промовив про жертовник у Вефилі і про всі капища на висотах, у містах самарійських.","І після цієї події Ієровоам не зійшов зі своєї поганої дороги, але продовжував ставити з народу священиків висот; хто хотів, того він посвячував, і той ставав священиком висот.","Це вело дім Ієровоамів до гріха і до загибелі і до знищення його з лиця землі."],"x":{"1":"6.13.6|10.12.33","2":"11.23.16","3":"4.13.1","6":"1.8.8|1.9.28|54.8.24","8":"3.22.18","11":"11.23.18","18":"64.11.13|65.1.8|62.7.11","22":"10.14.13|31.14.19|32.22.19","24":"10.20.36","25":"10.13.11","30":"10.13.22","31":"11.23.18","33":"1.28.41|2.7.37","34":"10.12.30|8.2.25"}},{"v":["У той час занедужав Авия, син Ієровоамів.","І сказав Ієровоам дружині своїй: встань і переодягнися, щоб не довідалися, що ти дружина Ієровоамова, і піди в Силом. Там є пророк Ахия; він передрік мені, що я буду царем цього народу.","І візьми із собою [для чоловіка Божого] десять хлібів, і коржів, і глечик меду, і піди до нього: він скаже тобі, що буде з сином.","Дружина Ієровоама так і зробила: встала, пішла в Силом і прийшла в дім Ахиї. Ахия вже не міг бачити, бо очі його зробилися нерухомі від старости.","І сказав Господь Ахиї: ось, іде дружина Ієровоамова запитати тебе про сина свого, тому що він хворий; так і так говори їй; вона прийде переодягнена.","Ахия, почувши шерех від ніг її, коли вона ввійшла у двері, сказав: увійди, дружино Ієровоамова; для чого було тобі переодягатися? Я грізний посланець до тебе.","Піди, скажи Ієровоаму: так говорить Господь Бог Ізраїлів: Я підняв тебе із середовища простого народу і поставив вождем народу Мого Ізраїля,","і відторгнув царство від дому Давидового і дав його тобі; а ти не такий, як раб Мій Давид, який дотримувався заповідей Моїх і який ішов за Мною всім серцем своїм, роблячи тільки угодне перед очима Моїми;","ти чинив гірше за всіх, які були раніше тебе, і пішов, і зробив собі інших богів і ідолів, щоб прогнівати Мене, Мене ж відкинув назад;","за це Я наведу лиха на дім Ієровоамів і знищу в Ієровоама до того, хто мочиться до стіни, ув’язненого і хто залишився в Ізраїлі, і вимету дім Ієровоамів, як вимітають сміття, дочиста;","хто помре в Ієровоама в місті, того з’їдять пси, а хто помре на полі, того склюють птахи небесні; так Господь сказав.","Встань і йди в дім твій; і як тільки нога твоя ступить у місто, помре син;","і оплачуть його всі ізраїльтяни і поховають його, бо він один у Ієровоама ввійде в гробницю, тому що в ньому, з дому Ієровоамового, знайшлося щось добре перед Господом Богом Ізраїлевим.","І поставить Собі Господь над Ізраїлем царя, який знищить дім Ієровоамів у той день; і що? навіть тепер.","І вразить Господь Ізраїля, і буде він , як очерет, що колишеться у воді, і викине ізраїльтян з цієї доброї землі, яку дав батькам їхнім, і розвіє їх за ріку, за те, що вони зробили в себе ідолів, дратуючи Господа;","і видасть [Господь] Ізраїля за гріхи Ієровоама, які він сам учинив і якими ввів у гріх Ізраїля.","І встала дружина Ієровоамова, і пішла, і прийшла у Фирцу; і лише тільки переступила через поріг дому, син помер.","І поховали його, й оплакали його всі ізраїльтяни, за словом Господа, яке Він прорік через раба Свого Ахию пророка.","Інші діла Ієровоама, як він воював і як царював, описані у літописі царів ізраїльських.","Царював Ієровоам двадцять два роки; і спочив він з батьками своїми, і став царем Нават, син його, замість нього.","Ровоам, син Соломонів, царював у Юдеї. Сорок один рік було Ровоаму, коли він став царем, і сімнадцять років царював у Єрусалимі, у місті, яке обрав Господь із усіх колін Ізраїлевих, щоб перебувало там ім’я Його. Ім’я матері його Наама аммонитянка.","І робив Іуда невгодне перед очима Господа, і прогнівляли Його більше всього того, що зробили батьки їхні своїми гріхами, якими вони грішили.","І спорудили вони собі висоти й ідолів і капища на всякому високому пагорбі і під усяким тінистим деревом.","І блудники були також у цій землі і робили всі мерзоти тих народів, яких Господь прогнав від лиця синів Ізраїлевих.","На п’ятому році царювання Ровоамового, Сусаким, цар Єгипетський, виступив проти Єрусалима","і взяв скарби дому Господнього і скарби дому царського [і золоті щити, які взяв Давид від рабів Адраазара, царя Сувського, і вніс у Єрусалим]. Усе взяв; взяв і всі золоті щити, які зробив Соломон.","І зробив цар Ровоам замість них мідні щити і віддав їх у руки начальникам охоронців, які охороняли вхід у дім царя.","Коли цар виходив у дім Господній, охоронці несли їх, і потім знову відносили їх у палату охоронців.","Інше про Ровоама і про все, що він робив, описано в літописі царів юдейських.","Між Ровоамом та Ієровоамом була війна в усі дні життя їхнього .","І спочив Ровоам з батьками своїми і похований з батьками своїми в місті Давидовому. Ім’я матері його Наама аммонитянка. І став царем Авия, син його, замість нього."],"x":{"2":"10.11.31","3":"8.9.7","7":"10.1.35","8":"10.11.31","9":"17.9.26","10":"10.15.29","13":"10.13.22|29.4.14","14":"10.15.29","15":"13.13.17|11.17.6","16":"10.12.28","17":"10.11.26","18":"10.14.13|13.10.15","19":"13.10.15","21":"13.12.13","22":"13.12.1","23":"1.20.4|4.12.2|11.16.4","24":"4.18.9|11.21.11|13.33.2","25":"13.12.2","26":"10.10.16","27":"13.12.10","29":"13.12.15","30":"10.15.6:16","31":"4.31.16|13.12.16"}},{"v":["У вісімнадцятий рік царювання Ієровоама, сина Наватового, Авия став царем над юдеями.","Три роки він царював у Єрусалимі; ім’я матері його Мааха, дочка Авессалома.","Він ходив у всіх гріхах батька свого, які той робив раніше нього, і серце його не було віддане Господу Богу його, як серце Давида, батька його.","Але заради Давида Господь Бог його дав йому світильник в Єрусалимі, поставивши після нього сина його й утвердивши Єрусалим,","тому що Давид робив угодне перед очима Господа і не відступав від усього того, що Він заповів йому, в усі дні життя свого, крім вчинку з Урією хеттеянином.","І війна була між Ровоамом та Ієровоамом в усі дні життя їхнього.","Інші діла Авиї, усе, що він зробив, записано в літописі царів юдейських. І була війна між Авиєю і Ієровоамом.","І спочив Авия з батьками своїми, і поховали його в місті Давидовому. І став царем Аса, син його, замість нього.","У двадцятий рік царювання Ієровоама, царя Ізраїльського, став царем Аса над юдеями","і сорок один рік царював у Єрусалимі; ім’я матері його Ана́, дочка Авессалома.","Аса робив угодне перед очима Господа, як Давид, батько його.","Він вигнав блудників із землі і викинув усіх ідолів, яких зробили батьки його,","і навіть матір свою Ану́ позбавив звання цариці за те, що вона зробила ідола Астарти; і порубав Аса ідола її і спалив біля потоку Кедрона.","Висоти ж не були знищені. Але серце Аси було віддано Господу в усі дні його.","І вніс він у дім Господній речі, освячені батьком його, і речі, освячені ним: срібло і золото і сосуди.","І війна була між Асою і Ваасою, царем Ізраїльським, в усі дні їхні.","І вийшов Вааса, цар Ізраїльський, проти Юдеї і почав будувати Раму, щоб ніхто не виходив і не йшов до Аси, царя Юдейського.","І взяв Аса все срібло і золото, що залишалося в скарбницях дому Господнього й у скарбницях дому царського, і дав його в руки слуг своїх, і послав їх цар Аса до Венадада, сина Тавримона, сина Хезионового, царя Сирійського, який жив у Дамаску, і сказав:","союз нехай буде між мною і між тобою, як був між батьком моїм і між батьком твоїм; ось, я посилаю тобі в дарунок срібло і золото; розірви союз твій з Ваасою, царем Ізраїльським, щоб він відійшов від мене.","І послухався Венадад царя Аси, і послав воєначальників своїх проти міст ізраїльських, і вразив Аїн і Дан і Авел-Беф-Мааху і весь Киннероф, по всій землі Неффалима.","Почувши про це , Вааса припинив будувати Раму і повернувся у Фирцу.","Цар же Аса скликав усіх юдеїв, нікого не виключаючи, і винесли вони з Рами каміння і дерева, що Вааса вживав для будівництва. І побудував з них цар Аса Гиву Веніамінову і Мицпу.","Всі інші діла Аси і всі подвиги його, і все, що він зробив, і міста, які він побудував, описані у літописі царів юдейських, крім того, що в старості своїй він був хворий на ноги.","І спочив Аса з батьками своїми і похований з батьками своїми в місті Давида, батька свого. І став царем Іосафат, син його, замість нього.","Нават же, син Ієровоамів, став царем над Ізраїлем на другий рік Аси, царя Юдейського, і царював над Ізраїлем два роки.","І робив він неугодне перед очима Господа, ходив шляхом батька свого і в гріхах його, якими той увів Ізраїля у гріх.","І зробив проти нього змову Вааса, син Ахиї, з дому Іссахарового, й убив його Вааса біля Гавафона филистимського, коли Нават і всі ізраїльтяни облягали Гавафон:","і умертвив його Вааса на третій рік Аси, царя Юдейського, і став царем замість нього.","Коли він став царем, то вибив увесь дім Ієровоамів, не залишив ні душі в Ієровоама, доки не знищив його, за словом Господа, яке Він прорік через раба Свого Ахию силомлянина,","за гріхи Ієровоама, які він сам робив і якими ввів у гріх Ізраїля, за образу, якою він прогнівив Господа Бога Ізраїлевого.","Інші діла Навата, все, що він зробив, описано в літописі царів ізраїльських.","І війна була між Асою і Ваасою, царем Ізраїльським, в усі дні їхні.","На третій рік Аси, царя Юдейського, став царем Вааса, син Ахиї, над усіма ізраїльтянами у Фирці і царював двадцять чотири роки.","І робив неугодне перед очима Господніми і ходив шляхом Ієровоама й у гріхах його, якими той увів у гріх Ізраїля."],"x":{"1":"13.13.1","2":"13.11.20","3":"13.12.14|10.14.8","4":"10.11.36|11.8.19","5":"9.11.4:17","7":"13.13.3","8":"13.14.1","10":"13.13.2","12":"4.23.17|10.14.24","13":"13.15.16","14":"2.26.30|10.22.43|13.15.17","16":"10.14.30|13.16.9","17":"13.16.1","18":"11.12.18|13.16.2","20":"13.16.4|0.14.14","21":"13.16.5","22":"5.18.24","23":"13.14.2","24":"13.16.13","26":"10.12.33","27":"10.14.14|5.19.44","28":"10.16.7","29":"10.14.10|11.9.9","30":"30.47.29","31":"10.16.5","32":"10.15.16|13.16.9","34":"10.15.26"}},{"v":["І було слово Господнє до Іуя, сина Ананієвого, про Ваасу:","за те, що Я підняв тебе з пороху і зробив тебе вождем народу Мого Ізраїля, ти ж пішов шляхом Ієровоама і ввів у гріх народ Мій ізраїльтян, щоб він прогнівляв Мене гріхами своїми,","ось, Я відкину дім Вааси і дім потомства його і зроблю з домом твоїм те саме, що з домом Ієровоама, сина Наватового;","хто помре у Вааси в місті, того з’їдять пси; а хто помре в нього на полі, того склюють птахи небесні.","Інші діла Вааси, все, що́ він зробив, і подвиги його описані в літописі царів ізраїльських.","І спочив Вааса з батьками своїми, і похований у Фирці. І став царем Ила, син його, замість нього.","Але через Іуя, сина Ананієвого, уже було сказане слово Господнє про Ваасу і про дім його і про все зло, яке він учинив перед очима Господа, прогнівляючи Його ділами рук своїх, наслідуючи дім Ієровоамів, за що́ він знищений був.","У двадцять шостий рік Аси, царя Юдейського, став царем Ила, син Вааси, над Ізраїлем у Фирці, і царював два роки.","І вчинив проти нього змову раб його Замврій, який був начальником над половиною колісниць. Коли він у Фирці напився доп’яну в домі Арси, який начальствував над палацом у Фирці,","тоді ввійшов Замврій, уразив його і умертвив його, у двадцять сьомий рік Аси, царя Юдейського, і став царем замість нього.","Коли він став царем і сів на престолі його, то знищив увесь дім Вааси, не залишивши йому того, хто мочиться до стіни, ні родичів його, ні друзів його.","І знищив Замврій весь дім Вааси, за словом Господа, яке Він прорік про Ваасу через Іуя пророка,","за всі гріхи Вааси і за гріхи Или, сина його, які вони самі чинили і якими вводили Ізраїля в гріх, прогнівляючи Господа Бога Ізраїлевого своїми ідолами.","Інші діла Или, все, що він зробив, описано в літописі царів ізраїльських.","У двадцять сьомий рік Аси, царя Юдейського, став царем Замврій і царював сім днів у Фирці, коли народ облягав Гавафон филистимський.","Коли народ, який облягав, почув, що Замврій учинив змову й умертвив царя, то всі ізраїльтяни поставили царем Амврія, воєначальника, над Ізраїлем у той же день, у стані.","І відступили Амврій і всі ізраїльтяни з ним від Гавафона й обложили Фирцу.","Коли побачив Замврій, що місто взяте, увійшов у внутрішню кімнату царського дому і запалив за собою царський дім вогнем і загинув","за свої гріхи, у чому він згрішив, роблячи неугодне перед очима Господніми, ходячи шляхом Ієровоама й у гріхах його, які той учинив, щоб увести Ізраїля в гріх.","Інші діла Замврія і змова його, яку він учинив, описані в літописі царів ізраїльських.","Тоді розділився народ ізраїльський надвоє: половина народу стояла за Фамнія, сина Гонафового, щоб поставити царем його, а половина за Амврія.","І взяв гору народ, який за Амврія, над народом, який за Фамнія, сина Гонафового, і помер Фамній, і став царем Амврій.","На тридцять першому році Аси, царя Юдейського, став царем Амврій над Ізраїлем і царював дванадцять років. У Фирці він царював шість років.","І купив Амврій гору Семерон у Семира за два таланти срібла, і забудував гору, і назвав побудоване ним місто Самарією, за ім’ям Семира, власника гори.","І робив Амврій неугодне перед очима Господа і чинив гірше за всіх, які були перед ним.","Він у всьому ходив шляхом Ієровоама, сина Наватового, й у гріхах його, якими той увів у гріх ізраїльтян, щоб прогнівляти Господа Бога Ізраїлевого ідолами своїми.","Інші діла Амврія, які він учинив, і мужність, яку він показав, описані у літописі царів ізраїльських.","І спочив Амврій з батьками своїми і похований у Самарії. І став царем Ахав, син його, замість нього.","Ахав, син Амвріїв, став царем над Ізраїлем у тридцять восьмий рік Аси, царя Юдейського, і царював Ахав, син Амврія, над Ізраїлем у Самарії двадцять два роки.","І робив Ахав, син Амврія, неугодне перед очима Господа більше за усіх, які були раніше нього.","Мало було для нього впадати у гріхи Ієровоама, сина Наватового; він узяв собі за дружину Ієзавель, дочку Ефваала, царя Сидонського, і став служити Ваалу і поклонятися йому.","І поставив він Ваалу жертовник у капищі Ваала, яке побудував у Самарії.","І зробив Ахав діброву, і більше за усіх царів ізраїльських, які були раніше нього, Ахав робив те, що прогнівляло Господа Бога Ізраїлевого, [і погубив душу свою].","В його дні Ахиїл вефилянин побудував Єрихон: на первістку своєму Авирамі він поклав підвалини його і на молодшому своєму сині Сегубі поставив ворота його, за словом Господа, яке Він прорік через Ісуса, сина Навина."],"x":{"1":"12.25.4","3":"11.9.9|10.15.29","4":"10.21.24","5":"13.16.11","7":"11.9.9|10.15.28-29","8":"10.14.17","10":"11.9.31","13":"10.15.34","15":"10.15.27","16":"11.8.26","17":"11.15.14","18":"43.6.16","19":"10.15.26:34","26":"10.15.26","30":"11.10.18","31":"76.2.20","33":"4.7.5|11.13.6","34":"5.6.25"}},{"v":["І сказав Ілля [пророк], фесвитянин, із жителів галаадських, Ахаву: живий Господь Бог Ізраїлів, перед Яким я стою! в ці роки не буде ні роси, ні дощу, хіба тільки за моїм словом.","І було до нього слово Господнє:","піди звідси і повернися на схід і сховайся біля потоку Хорафа, що навпроти Йордану;","з цього потоку ти будеш пити, а во́ронам Я повелів годувати тебе там.","І пішов він і зробив за словом Господнім; пішов і залишився біля потоку Хорафа, що навпроти Йордану.","І во́рони приносили йому хліб і м’ясо вранці, і хліб і м’ясо ввечері, а з потоку він пив.","Коли минув деякий час, цей поток висох, бо не було дощу на землю.","І було до нього слово Господнє:","встань і піди в Сарепту сидонську, і залишайся там; Я повелів там жінці вдові годувати тебе.","І встав він і пішов у Сарепту; і коли прийшов до воріт міста, ось, там жінка вдова збирає дрова. І покликав він її і сказав: дай мені трохи води в посудині напитися.","І пішла вона, щоб взяти; а він закричав услід їй і сказав: візьми для мене і шматок хліба в руки свої.","Вона сказала: живий Господь Бог твій! у мене нічого немає печеного, а тільки є жменя борошна в діжці і трохи олії в глечику; і ось, я наберу поліна два дров, і піду, і приготую це для себе і для сина мого; з’їмо це і помремо.","І сказав їй Ілля: не бійся, піди, зроби, що́ ти сказала; але раніше з цього зроби невеликий опріснок для мене і принеси мені; а для себе і для свого сина зробиш після;","бо так говорить Господь Бог Ізраїлів: борошно в діжці не вичерпається, і олія в глечику не убуде до того дня, коли Господь дасть дощ на землю.","І пішла вона і зробила так, як сказав Ілля; і годувалася вона, і він, і дім її деякий час.","Борошно в діжці не вичерпувалося, й олія в глечику не убувала, за словом Господа, яке Він прорік через Іллю.","Після цього занедужав син цієї жінки, господині дому, і хвороба його була така сильна, що не залишилося в ньому дихання.","І сказала вона Іллі: що мені і тобі, чоловіче Божий? ти прийшов до мене нагадати гріхи мої й умертвити сина мого.","І сказав він їй: дай мені сина твого. І взяв його з рук її, і поніс його у світлицю, де він жив, і поклав його на свою постіль,","і воззвав до Господа і сказав: Господи Боже мій! невже Ти і вдові, у якої я перебуваю, зробиш зло, умертвивши сина її?","І простягнувшись над отроком тричі, він воззвав до Господа і сказав: Господи Боже мій! нехай повернеться душа отрока цього в нього!","І почув Господь голос Іллі, і повернулася душа отрока цього в нього, і він ожив.","І взяв Ілля отрока, і вивів його зі світлиці в дім, і віддав його матері його, і сказав Ілля: дивися, син твій живий.","І сказала та жінка Іллі: тепер-то я узнала, що ти чоловік Божий, і що слово Господнє в устах твоїх істинне."],"x":{"1":"30.48.3|55.5.17","4":"25.146.9","9":"41.1.20|52.21.2|54.28.2","10":"52.4.26","12":"10.18.10","19":"11.4.32","20":"54.28.8","21":"16.7.39|54.20.10","22":"75.11.35","23":"10.17.18"}},{"v":["Коли минуло багато днів, було слово Господнє до Іллі на третій рік: піди і покажися Ахаву, і Я дам дощ на землю.","І пішов Ілля, щоб показатися Ахаву. Голод же сильний був у Самарії.","І покликав Ахав Авдія, який був начальником над палацом. Авдій же був чоловіком дуже богобоязким,","і коли Ієзавель знищувала пророків Господніх, Авдій узяв сто пророків, і переховував їх, по п’ятдесят чоловік, у печерах, і годував їх хлібом і водою.","І сказав Ахав Авдію: піди по землі до всіх джерел водних і до всіх потоків на землі, чи не знайдемо де трави, щоб нам нагодувать коней і ослів і не позбутися худоби.","І розділили вони між собою землю, щоб обійти її: Ахав окремо пішов однією дорогою, і Авдій окремо пішов іншою дорогою.","Коли Авдій ішов дорогою, ось, назустріч йому іде Ілля. Він упізнав його і упав на лице своє і сказав: чи це ти, господарю мій Іллє?","Той сказав йому: я; піди, скажи господарю твоєму: «Ілля тут».","Він сказав: чим я завинив, що ти віддаєш раба твого у руки Ахава, щоб умертвити мене?","Живий Господь Бог твій! немає жодного народу і царства, куди б не посилав господар мій шукати тебе; і коли йому говорили, що тебе нема, він брав клятву з того царства і народу, що не могли відшукати тебе;","а ти тепер говориш: «піди, скажи господарю твоєму: Ілля тут».","Коли я піду від тебе, тоді Дух Господній віднесе тебе, не знаю куди; і якщо я піду повідомити Ахава, і він не знайде тебе, то він уб’є мене; а раб твій богобоязкий від юности своєї.","Хіба не сказано господарю моєму, що́ я зробив, коли Ієзавель убивала пророків Господніх, як я переховував сто чоловік пророків Господніх, по п’ятдесят чоловік, у печерах і годував їх хлібом і водою?","А ти тепер говориш: «піди, скажи господарю твоєму: Ілля тут»; він уб’є мене.","І сказав Ілля: живий Господь Саваоф, перед Яким я стою! сьогодні я покажуся йому.","І пішов Авдій назустріч Ахаву і доніс йому. І пішов Ахав назустріч Іллі.","Коли Ахав побачив Іллю, то сказав Ахав йому: чи це ти, який бентежить Ізраїля?","І сказав Ілля: не я бентежу Ізраїля, а ти і дім батька твого, тим, що ви знехтували повеління Господні й ідете услід Ваалам;","тепер пошли і збери до мене весь Ізраїль на гору Кармил, і чотириста п’ятдесят пророків Ваалових, і чотириста пророків дібровних, які годуються від столу Ієзавелі.","І послав Ахав до всіх синів Ізраїлевих і зібрав усіх пророків на гору Кармил.","І підійшов Ілля до всього народу і сказав: чи довго вам кульгати на обидва коліна? якщо Господь є Бог, то йдіть за Ним; а якщо Ваал, то за ним ідіть. І не відповів народ йому ні слова.","І сказав Ілля народу: я один залишився пророк Господній, а пророків Ваалових чотириста п’ятдесят чоловік [і чотириста пророків дібровних];","нехай дадуть нам двох тельців, і нехай вони виберуть собі одного тельця, і розсічуть його, і покладуть на дрова, але вогню нехай не підкладають; а я приготую другого тельця і покладу на дрова, а вогню не підкладу;","і закличте ви ім’я бога вашого, а я закличу ім’я Господа Бога мого. Той Бог, Який дасть відповідь за допомогою вогню, є Бог. І відповів весь народ і сказав: добре, [нехай буде так].","І сказав Ілля пророкам Вааловим: виберіть собі одного тельця і приготуйте ви раніше, бо вас багато; і закличте ім’я бога вашого, але вогню не підкладайте.","І взяли вони тельця, якого дали їм, і приготували, і заклика́ли ім’я Ваала від ранку до півдня, говорячи: Ваале, почуй нас! Але не було ні голосу, ні відповіді. І скакали вони біля жертовника, який зробили.","Опівдні Ілля став глузувати з них і говорив: кричіть гучним голосом, бо він бог; може, він задумався, або зайнятий чим-небудь, або в дорозі, а можливо, і спить, то він прокинеться!","І стали вони кричати гучним голосом, і кололи себе за своїм звичаєм ножами і списами, так що кров лилася по них.","Минув полудень, а вони все ще біснувалися до самого часу вечірнього жертвоприношення; але не було ні голосу, ні відповіді, ні чутки. [І сказав Ілля фесвитянин пророкам Вааловим: тепер відійдіть, щоб і я звершив моє жертвоприношення. Вони відійшли і замовкли.]","Тоді Ілля сказав усьому народові: підійдіть до мене. І підійшов весь народ до нього. Він відновив зруйнований жертовник Господній.","І взяв Ілля дванадцять каменів, за числом колін синів Якова, якому Господь сказав так: Ізраїль буде ім’я твоє.","І побудував з цих каменів жертовник в ім’я Господа, і зробив навколо жертовника рів, місткістю у дві сати зерна,","і поклав дрова [на жертовник], і розсік тельця, і поклав його на дрова,","і сказав: наповніть чотири відра водою і вилийте на жертву всепалення і на дрова. [І зробили так.] Потім сказав: повторіть. І вони повторили. І сказав: зробіть те саме третій раз. І зробили втретє,","і вода полилася навколо жертовника, і рів наповнився водою.","Під час приношення вечірньої жертви підійшов Ілля пророк [і воззвав до неба] і сказав: Господи, Боже Авраамів, Ісааків та Ізраїлів! [Почуй мене, Господи, почуй мене нині у вогні!] Нехай пізнають у цей день [люди ці], що Ти один Бог в Ізраїлі, і що я раб Твій і зробив усе за словом Твоїм.","Почуй мене, Господи, почуй мене! Нехай пізнає народ цей, що Ти, Господи, Бог, і Ти навернеш серце їх [до Тебе].","І зійшов вогонь Господній і пожер всепалення, і дрова, і камені, і порох, і поглинув воду, що у рові.","Побачивши це , весь народ упав на лице своє і сказав: Господь є Бог, Господь є Бог!","І сказав їм Ілля: схопіть пророків Ваалових, щоб жоден з них не сховався. І схопили їх, і відвів їх Ілля до потоку Киссону і заколов їх там.","І сказав Ілля Ахаву: піди, їж і пий, бо чути шум дощу.","І пішов Ахав їсти і пити, а Ілля зійшов на верхівку Кармила і схилився до землі, і поклав лице своє між колінами своїми,","і сказав слузі своєму: піди, подивися до моря. Той пішов і подивився, і сказав: нічого немає. Він сказав: продовжуй це до семи разів.","На сьомий раз той сказав: ось, невелика хмарка піднімається від моря, завбільшки в долоню людську. Він сказав: піди, скажи Ахаву: «запрягай [колісницю твою] і від’їжджай, щоб не застав тебе дощ».","Тим часом небо зробилося похмурим від хмар і від вітру, і пішов великий дощ. Ахав же сів у колісницю, [заплакав] і поїхав у Ізреель.","І була на Іллі рука Господня. Він оперезав стегна свої і біг перед Ахавом до самого Ізрееля."],"x":{"1":"10.17.8","4":"10.16.31","10":"10.17.12","12":"11.2.16|36.3.12|52.4.1","15":"11.3.14","17":"13.18.19|52.23.2|54.24.5","19":"5.19.26|11.2.25|31.35.2","20":"13.18.5","21":"55.1.8|30.2.12","22":"10.22.6","24":"2.9.24","27":"4.32.37","28":"2.19.28|4.14.1","29":"1.29.39|37.9.21|54.3.1","31":"0.32.28|11.17.34","32":"0.13.18|4.12.13","36":"1.3.6|1.4.5|12.29.18","38":"2.9.24|6.6.21|13.7.1","39":"48.13.9","40":"6.4.7|4.13.5|8.15.33","42":"55.5.16","45":"24.37.6|55.5.18|10.17.1","46":"52.1.66"}},{"v":["І переповів Ахав Ієзавелі все, що зробив Ілля, і те, що він убив усіх пророків мечем.","І послала Ієзавель посланця до Іллі сказати: [якщо ти Ілля, а я Ієзавель, то] нехай те і те зроблять мені боги, і ще більше зроблять, якщо я завтра до цього часу не зроблю з твоєю душею того, що зроблено з душею кожного з них.","Побачивши це, він встав і пішов, щоб урятувати життя своє, і прийшов у Вирсавію, що в Юдеї, і залишив слугу свого там.","А сам відійшов у пустелю на день путі і, прийшовши, сів під ялівцевим кущем, і просив смерти собі і сказав: досить уже, Господи; візьми душу мою, бо я не кращий за батьків моїх.","І ліг і заснув під ялівцевим кущем. І ось, ангел торкнувся його і сказав йому: встань, їж [і пий].","І глянув Ілля, і ось, біля голови його печений корж і глечик води. Він поїв і напився і знову заснув.","І повернувся ангел Господній удруге, торкнувся його і сказав: встань, їж [і пий], бо далека дорога перед тобою.","І встав він, поїв і напився, і, підкріпившись тією їжею, йшов сорок днів і сорок ночей до гори Божої Хорива.","І увійшов він там у печеру і ночував у ній. І ось, було до нього слово Господнє, і сказав йому Господь : що ти тут, Іллє?","Він сказав: поревнував я за Господа Бога Саваофа, тому що сини Ізраїлеві залишили завіт Твій, зруйнували Твої жертовники і пророків Твоїх убили мечем; залишився я один, але і моєї душі шукають, щоб відняти її.","І сказав: вийди і стань на горі перед лицем Господнім, і ось, Господь пройде, і великий і сильний вітер, що роздирає гори і розтрощує скелі перед Господом, але не у вітрі Господь; після вітру землетрус, але не в землетрусі Господь;","після землетрусу вогонь, але не у вогні Господь; після вогню віяння тихого вітру, [і там Господь].","Почувши це , Ілля закрив лице своє милоттю своєю, і вийшов, і став біля входу в печеру. І був до нього голос і сказав йому: що ти тут, Іллє?","Він сказав: поревнував я за Господа Бога Саваофа, бо сини Ізраїлеві залишили завіт Твій, зруйнували жертовники Твої і пророків Твоїх убили мечем; залишився я один, але і моєї душі шукають, щоб відняти її.","І сказав йому Господь: піди назад своєю дорогою через пустелю в Дамаск, і коли прийдеш, то помаж Азаїла на царя над Сирією,","а Іиуя, сина Намессіїного, помаж на царя над Ізраїлем; Єлисея ж, сина Сафатового, з Авел-Мехоли, помаж на пророка замість себе;","хто втече від меча Азаїлового, того умертвить Іиуй; а хто врятується від меча Іиуєвого, того умертвить Єлисей.","Утім, Я залишив між ізраїльтянами сім тисяч [мужів]; всіх цих коліна не схилялися перед Ваалом, і всіх цих уста не цілували його.","І пішов він звідти, і знайшов Єлисея, сина Сафатового, коли він орав; дванадцять пар [волів] було в нього, і сам він був при дванадцятій. Ілля, проходячи повз нього, кинув на нього милоть свою.","І залишив [Єлисей] волів, і побіг за Іллею, і сказав: дозволь мені поцілувати батька мого і матір мою, і я піду за тобою. Він сказав йому: піди і приходь назад, бо що зробив я тобі?","Він, відійшовши від нього, взяв пару волів і заколов їх і, запаливши плуг волів, засмажив м’ясо їх, і роздав людям, і вони їли. А сам встав і пішов за Іллею, і став служити йому."],"x":{"1":"10.18.40","2":"10.2.23","3":"0.21.31","4":"6.16.30|55.5.17|24.7.16","8":"1.3.1|1.24.18|50.4.2","9":"10.18.9","10":"62.11.3","11":"1.33.22|24.38.1|54.2.2","13":"1.3.6","14":"10.19.10|25.68.10|62.11.3","16":"11.9.1-2|30.48.8","17":"11.9.24|13.22.8","18":"62.11.4","19":"11.1.8|48.13.4","21":"8.6.14"}},{"v":["Венадад, цар Сирійський, зібрав усе своє військо, і з ним були тридцять два царі, і коні і колісниці, і пішов, обложив Самарію і воював проти неї.","І послав послів до Ахава, царя Ізраїльського, у місто,","і сказав йому: так говорить Венадад: срібло твоє і золото твоє — мої, і дружини твої і кращі сини твої — мої.","І відповів цар Ізраїльський і сказав: нехай буде за словом твоїм, господарю мій царю: я і все моє — твоє.","І знову прийшли посли і сказали: так говорить Венадад: я послав до тебе сказати: «срібло твоє, і золото твоє, і дружин твоїх, і синів твоїх віддай мені»;","тому я завтра, до цього часу, пошлю до тебе рабів моїх, щоб вони оглянули твій дім і доми тих, що служать при тобі, і все дороге для очей твоїх узяли у свої руки і винесли.","І скликав цар Ізраїльський усіх старійшин землі і сказав: зауважте і дивіться, він замишляє зло; коли він посилав до мене за дружинами моїми, і синами моїми, і сріблом моїм, і золотом моїм, я йому не відмовив.","І сказали йому всі старійшини і весь народ: не слухай і не погоджуйся.","І сказав він послам Венадада: скажіть господареві моєму цареві: усе, щодо чого ти посилав у перший раз до раба твого, я готовий зробити, а цього не можу зробити. І пішли посли і віднесли йому відповідь.","І послав до нього Венадад сказати: нехай те і те зроблять мені боги, і ще більше зроблять, якщо пороху самарійського вистачить по жмені для всіх людей, які йдуть за мною.","І відповів цар Ізраїльський і сказав: скажіть: нехай не хвалиться той, хто підперізується, як той, хто розперізується.","Почувши це слово, Венадад, який пив разом з царями в наметах, сказав рабам своїм: облягайте місто. І вони облягли місто.","І ось, один пророк підійшов до Ахава, царя Ізраїльського, і сказав: так говорить Господь: чи бачиш усе це велике полчище? ось, Я сьогодні віддам його в руку твою, щоб ти знав, що Я Господь.","І сказав Ахав: через кого? Він сказав: так говорить Господь: через слуг обласних начальників. І сказав [Ахав]: хто почне битву? Він сказав: ти.","[Ахав] перелічив слуг обласних начальників, і знайшлося їх двісті тридцять два; після них перелічив увесь народ, усіх синів Ізраїлевих, сім тисяч.","І вони виступили опівдні. Венадад же напився доп’яну в наметах разом з царями, із тридцятьма двома царями, які допомагали йому.","І виступили спершу слуги обласних начальників. І послав Венадад, і донесли йому, що люди вийшли із Самарії.","Він сказав: якщо за миром вийшли вони, то схопіть їх живими, і якщо на війну вийшли, також схопіть їх живими.","Вийшли з міста слуги обласних начальників, і військо за ними.","І вражав кожен супротивника свого; і побігли сиріяни, а ізраїльтяни погналися за ними. Венадад же, цар Сирійський, урятувався на коні з вершниками.","І вийшов цар Ізраїльський, і взяв коней і колісниці, і зробив велику поразку серед сиріян.","І підійшов пророк до царя Ізраїльського і сказав йому: піди, зміцнися, і знай і дивися, що тобі робити, бо через рік цар Сирійський знову піде проти тебе.","Слуги царя Сирійського сказали йому: Бог їхній є Бог гір, [а не Бог долин,] тому вони подолали нас; якщо ж ми будемо битися з ними на рівнині, то обов’язково подолаємо їх.","Отже, ось що зроби: віддали царів, кожного з місця його, і замість них постав областеначальников;","і набери собі війська стільки, скільки впало в тебе, і коней, скільки було коней, і колісниць, скільки було колісниць; і будемо битися з ними на рівнині, і тоді точно подолаємо їх. І послухався він голосу їхнього і зробив так.","Коли минув рік, Венадад зібрав сиріян і виступив до Афека, щоб битися з Ізраїлем.","Зібрані були і сини Ізраїлеві і, взявши продовольство, пішли назустріч їм. І розташувалися сини Ізраїлеві станом перед ними, наче два невеликі стада кіз, а сиріяни наповнили землю.","І підійшов чоловік Божий, і сказав цареві Ізраїльському: так говорить Господь: за те, що сиріяни говорять: «Господь є Бог гір, а не Бог долин», Я все це велике полчище віддам у руку твою, щоб ви знали, що Я — Господь.","І стояли станом одні навпроти других сім днів. У сьомий день почалася битва, і сини Ізраїлеві уразили сто тисяч піших сиріян в один день.","Інші втекли в місто Афек; там упала стіна на останніх двадцять сім тисяч чоловік. А Венадад пішов у місто і бігав з однієї внутрішньої кімнати в іншу.","І сказали йому слуги його: ми чули, що царі дому Ізраїлевого царі милостиві; дозволь нам покласти веретище на стегна свої і мотузки на голови свої і піти до царя Ізраїльського; може, він пощадить життя твоє.","І оперезали вони веретищем стегна свої і поклали мотузки на голови свої, і прийшли до царя Ізраїльського і сказали: раб твій Венадад говорить: «пощади життя моє». Той сказав: хіба він живий? він брат мій.","Люди ці прийняли це за добру ознаку і поспішно підхопили слово з вуст його і сказали: брат твій Венадад. І сказав він: підіть, приведіть його. І вийшов до нього Венадад, і він посадив його із собою на колісницю.","І сказав йому Венадад : міста, які взяв мій батько у твого батька, я поверну, і площі ти можеш мати для себе в Дамаску, як батько мій мав у Самарії. Ахав сказав : після договору я відпущу тебе. І, уклавши з ним договір, відпустив його.","Тоді один чоловік із синів пророчих сказав іншому, за словом Господа: бий мене. Але цей чоловік не погодився бити його.","І сказав йому: за те, що ти не слухаєш голосу Господа, уб’є тебе лев, коли підеш від мене. Він пішов від нього, і лев, зустрівши його, убив його.","І знайшов він іншого чоловіка, і сказав: бий мене. Цей чоловік бив його до того, що зранив побоями.","І пішов пророк і став перед царем на дорозі, прикривши покривалом очі свої.","Коли цар проїжджав мимо, він закричав цареві і сказав: раб твій ходив на битву, і ось, один чоловік, який відійшов у бік, підвів до мене чоловіка і сказав: «охороняй цього чоловіка; якщо його не стане, то твоя душа буде за його душу, або ти повинен будеш відважити талант срібла».","Коли раб твій зайнявся тими й іншими справами, його не стало. — І сказав йому цар Ізраїльський: такий тобі і вирок, ти сам вирішив.","Він негайно зняв покривало з очей своїх, і узнав його цар, що він із пророків.","І сказав йому: так говорить Господь: за те, що ти випустив з рук твоїх чоловіка, заклятого Мною, душа твоя буде замість його душі, народ твій замість його народу.","І вирушив цар Ізраїльський додому стривожений і засмучений, і прибув у Самарію."],"x":{"10":"10.19.2","11":"10.22.27","13":"10.18.4","27":"21.3.16","28":"11.19.22|1.15.3","30":"10.20.26|13.18.24","31":"11.6.26|22.10.25","34":"10.22.3","36":"10.13.24","42":"10.22.35"}},{"v":["І було після цих подій: у Навуфея ізреелитянина в Ізреелі був виноградник поряд з палацом Ахава, царя Самарійського.","І сказав Ахав Навуфею, говорячи: віддай мені свій виноградник; з нього буде в мене овочевий сад, бо він близько до мого дому; а замість нього я дам тобі виноградник кращий за цей, або, якщо вгодно тобі, дам тобі срібла, скільки він коштує.","Але Навуфей сказав Ахаву: вбережи мене Господь, щоб я віддав тобі спадщину батьків моїх!","І прийшов Ахав додому стривожений і засмучений тим словом, яке сказав йому Навуфей ізреелитянин, говорячи: не віддам тобі спадщини батьків моїх. І [у збентеженому дусі] ліг на постіль свою, і відвернув лице своє, і хліба не їв.","І ввійшла до нього дружина його Ієзавель і сказала йому: від чого стривожений дух твій, що ти і хліба не їси?","Він сказав їй: коли я став говорити Навуфею ізреелитянину і сказав йому: «віддай мені виноградник твій за срібло, або, якщо хочеш, я дам тобі інший виноградник замість нього», тоді він сказав: «не віддам тобі виноградника мого, [спадщини батьків моїх]».","І сказала йому Ієзавель, дружина його: що за царство було б в Ізраїлі, якби ти так робив? встань, їж хліб і будь спокійним; я дістану тобі виноградник Навуфея ізреелитянина.","І написала вона від імені Ахава листи, і запечатала їх його печаткою, і послала ці листи до старійшин і знатних у його місті, які живуть з Навуфеєм.","У листах вона писала так: оголосіть посаду і посадіть Навуфея на перше місце в народі;","і проти нього посадіть двох негідних людей, які свідчили б на нього і сказали: «ти хулив Бога і царя»; і потім виведіть його, і побийте його камінням, щоб він помер.","І зробили мужі міста його, старійшини і знатні, які жили в місті його, як наказала їм Ієзавель, так, як писано в листах, які вона послала до них.","Оголосили посаду і посадили Навуфея на чолі народу;","і виступили двоє негідних людей і сіли проти нього, і свідчили на нього ці недобрі люди перед народом, і говорили: Навуфей хулив Бога і царя. І вивели його за місто, і побили його камінням, і він помер.","І послали до Ієзавелі сказати: Навуфей побитий камінням і помер.","Почувши, що Навуфея побито камінням і він помер, Ієзавель сказала Ахаву: встань, візьми у володіння виноградник Навуфея ізреелитянина, який не хотів віддати тобі за срібло; бо Навуфея немає в живих, він помер.","Коли почув Ахав, що Навуфей [ізреелитянин] був убитий, [роздер одяг свій і надів на себе веретище, а потім] встав Ахав, щоб піти у виноградник Навуфея ізреелитянина і взяти його у володіння.","І було слово Господнє до Іллі фесвитянину:","встань, піди назустріч Ахаву, царю Ізраїльському, який у Самарії, ось, він тепер у винограднику Навуфея, куди прийшов, щоб узяти його у володіння;","і скажи йому: «так говорить Господь: ти убив, і ще вступаєш у спадщину?» і скажи йому: «так говорить Господь: на тім місці, де пси лизали кров Навуфея, пси будуть лизати і твою кров».","І сказав Ахав Іллі: знайшов ти мене, во́роже мій! Він сказав: знайшов, бо ти віддався тому, щоб робити неугодне перед очима Господа [і прогнівляти Його].","[Так говорить Господь:] ось, Я наведу на тебе лиха і вимету за тобою і знищу в Ахава того, хто мочиться до стіни, й ув’язненого, і хто залишився в Ізраїлі.","І зроблю з домом твоїм так, як зробив Я з домом Ієровоама, сина Наватового, і з домом Вааси, сина Ахиїного, за образу, якою ти прогнівив Мене і ввів Ізраїля в гріх.","Також і про Ієзавель сказав Господь: пси з’їдять Ієзавель за стіною Ізрееля.","Хто помре у Ахава в місті, того з’їдять пси, а хто помре на полі, того роздзьобають птахи небесні;","не було ще такого, як Ахав, який віддався б тому, щоб робити неугодне перед очима Господа, до чого підбурювала його дружина його Ієзавель;","він чинив дуже мерзенно, поклоняючись ідолам, як робили аморреї, яких Господь прогнав від лиця синів Ізраїлевих.","Вислухавши всі слова ці, Ахав [розчулився перед Господом, ходив і плакав,] роздер одяг свій, і поклав на тіло своє веретище, і постився, і спав у веретищі, і ходив сумний.","І було слово Господнє до Іллі фесвитянина [про Ахава], і сказав Господь:","бачиш, як смирився переді Мною Ахав? За те, що він смирився переді Мною, Я не наведу лиха у його дні; у дні сина його наведу лиха на дім його."],"x":{"1":"10.18.45","2":"2.25.14|4.11.10","3":"2.25.23|3.36.7|36.46.18","7":"50.6.24","10":"9.19.21|24.1.5","13":"25.34.11|50.26.60|2.24.11:14","15":"24.24.6","19":"10.22.38","20":"11.17.17","21":"11.9.8","22":"10.15.29","23":"11.9.36","24":"10.14.11","25":"10.21.20","26":"2.26.30","29":"13.12.7"}},{"v":["Прожили три роки, і не було війни між Сирією й Ізраїлем.","На третій рік Іосафат, цар Юдейський, пішов до царя Ізраїльського.","І сказав цар Ізраїльський слугам своїм: чи знаєте, що Рамоф галаадський наш? А ми так довго мовчимо, і не беремо його з руки царя Сирійського.","І сказав він Іосафату: чи підеш ти зі мною на війну проти Рамофа галаадського? І сказав Іосафат царю Ізраїльському: як ти, так і я; як твій народ, так і мій народ; як твої коні, так і мої коні.","І сказав Іосафат царю Ізраїльському: запитай сьогодні, що скаже Господь.","І зібрав цар Ізраїльський пророків, близько чотирьохсот чоловік, і сказав їм: чи йти мені війною на Рамоф галаадський, чи ні? Вони сказали: йди, Господь віддасть його в руки царя.","І сказав Іосафат: чи немає тут ще пророка Господнього, щоб нам запитати через нього Господа?","І сказав цар Ізраїльський Іосафату: є ще один чоловік, через якого можна запитати Господа, але я не люблю його, тому що він не пророкує про мене доброго, а тільки лихе, — це Михей, син Іємвлая. І сказав Іосафат: не говори, царю, так.","І покликав цар Ізраїльський одного євнуха і сказав: сходи скоріше за Михеєм, сином Іємвлая.","Цар Ізраїльський і Іосафат, цар Юдейський, сиділи кожен на сідалищі своєму, одягнені у царський одяг, на площі біля воріт Самарії, і всі пророки пророкували перед ними.","І зробив собі Седекія, син Хенаани, залізні роги, і сказав: так говорить Господь: цими забодаєш сиріян до знищення їх.","І всі пророки пророкували те саме, говорячи: йди на Рамоф галаадський, буде успіх, Господь віддасть його в руку царя.","Посланий, який пішов покликати Михея, говорив йому: ось, слова пророків одноголосно передвіщають цареві добре; нехай би і твоє слово було згідне зі словом кожного з них; проречи і ти добре.","І сказав Михей: живий Господь! я проречу те, що скаже мені Господь.","І прийшов він до царя. Цар сказав йому: Михею! чи йти нам війною на Рамоф галаадський, чи ні? І сказав той йому: йди, буде успіх, Господь віддасть його в руку царя.","І сказав йому цар: ще і ще заклинаю тебе, щоб ти не говорив мені нічого, крім істини в ім’я Господа.","І сказав він: я бачу всіх ізраїльтян, розсіяних по горах, як овець, у яких немає пастиря. І сказав Господь: немає в них начальника, нехай повертаються з миром кожен у свій дім.","І сказав цар Ізраїльський Іосафату: чи не говорив я тобі, що він не пророкує про мене доброго, а тільки лихе?","І сказав [Михей]: [не так; не я, а] вислухай слово Господнє: я бачив Господа, що сидить на престолі Своєму, і все воїнство небесне стояло при Ньому, праворуч і ліворуч від Нього;","і сказав Господь: хто схилив би Ахава, щоб він пішов і загинув у Рамофі галаадському? І один говорив так, інший говорив інакше;","і виступив один дух, став перед лицем Господа і сказав: я схилю його. І сказав йому Господь: чим?","Він сказав: я вийду і зроблюся духом неправдивим у вустах усіх пророків його. Господь сказав: ти схилиш його і виконаєш це; піди і зроби так.","І ось, тепер попустив Господь духа неправдивого у вуста всіх цих пророків твоїх; але Господь прорік про тебе недобре.","І підійшов Седекія, син Хенаани, і, вдаривши Михея по щоці, сказав: як, невже від мене відійшов Дух Господній, щоб говорити в тобі?","І сказав Михей: ось, ти побачиш це в той день, коли будеш бігати з однієї кімнати в іншу, щоб сховатися,","і сказав цар Ізраїльський: візьміть Михея і відведіть його до Амона градоначальника і до Іоаса, сина царя,","і скажіть: так говорить цар: посадіть цього у в’язницю і годуйте його скудно хлібом і скудно водою, доки я не повернусь у мирі.","І сказав Михей: якщо повернешся у мирі, то не Господь говорив через мене. І сказав: слухай, весь народе!","І пішов цар Ізраїльський та Іосафат, цар Юдейський, до Рамофа галаадського.","І сказав цар Ізраїльський Іосафату: я переодягнусь і вступлю в битву, а ти вдягни твій царський одяг. І переодягся цар Ізраїльський і вступив у битву.","Сирійський цар повелів начальникам колісниць, яких у нього було тридцять два, сказавши: не боріться ні з малим, ні з великим, а тільки з одним царем Ізраїльським.","Начальники колісниць, побачивши Іосафата, подумали: «мабуть, це цар Ізраїльський», і повернули на нього, щоб битися з ним . І закричав Іосафат.","Начальники колісниць, бачачи, що це не Ізраїльський цар, повернули від нього.","А один чоловік випадково натягнув лук і поранив царя Ізраїльського крізь шви лат. І сказав він своєму візникові: поверни назад і вивези мене з війська, бо я поранений.","Але битва у той день посилилася, і цар стояв на колісниці проти сиріян, і ввечері помер, і кров з рани лилася в колісницю.","І проголошено було по всьому стану при заходженні сонця: кожен іди у своє місто, кожен у свою землю!","І помер цар, і привезли його у Самарію, і поховали царя у Самарії.","І обмили колісницю на ставу самарійському, і пси лизали кров його, і обмивали блудниці, за словом Господа, яке Він прорік.","Інші діла Ахава, усе, що він робив, і дім зі слонової кістки, який він побудував, і всі міста, які він будував, описані у літописі царів ізраїльських.","І спочив Ахав з батьками своїми, і став царем Охозія, син його, замість нього.","Іосафат, син Аси, став царем Юдеї в четвертий рік Ахава, царя Ізраїльського.","Тридцяти п’яти років був Іосафат, коли став царем, і двадцять п’ять років царював у Єрусалимі. Ім’я матері його Азува, дочка Салаїля.","Він ходив у всьому шляхом батька свого Аси, не сходив з нього, роблячи угодне перед очима Господніми. Тільки висоти не були знищені; народ ще приносив жертви і куріння на висотах.","Іосафат уклав мир з царем Ізраїльським.","Інші діла Іосафата і подвиги його, які він звершив, і як він воював, описані у літописі царів юдейських.","І залишки блудників, які залишилися у дні батька його Аси, він знищив із землі.","В Ідумеї тоді не було царя; був намісник царський.","[Цар] Іосафат зробив кораблі на морі, щоб ходити в Офир за золотом; але вони не дійшли, бо розбилися в Еціон-Гавері.","Тоді сказав Охозія, син Ахава, Іосафату: нехай мої слуги підуть з твоїми слугами на кораблях. Але Іосафат не погодився.","І спочив Іосафат з батьками своїми і був похований з батьками своїми у місті Давида, батька свого. І став царем Іорам, син його, замість нього.","Охозія, син Ахава, став царем над Ізраїлем у Самарії, у сімнадцятий рік Іосафата, царя Юдейського, і царював над Ізраїлем [у Самарії] два роки,","і робив неугодне перед очима Господа, і ходив шляхом батька свого і шляхом матері своєї і шляхом Ієровоама, сина Наватового, який увів Ізраїля у гріх:","він служив Ваалу і поклонявся йому і прогнівив Господа Бога Ізраїлевого всім тим, що робив батько його."],"x":{"2":"13.18.2","3":"10.4.13","4":"13.18.3|11.3.7","5":"13.18.4","6":"13.18.5","7":"13.18.6","8":"10.20.13|72.4.3|65.4.16","11":"13.18.10|32.28.14","13":"13.18.12","14":"32.23.28|32.42.4","15":"13.18.14","16":"13.18.15","17":"3.27.17|13.18.16","18":"13.18.17","19":"31.6.1|37.4.14|37.7.9","21":"13.18.20|24.1.6","22":"13.18.21|36.14.9|50.6.13","23":"70.2.11","24":"13.18.23|32.20.2","25":"13.18.24","27":"10.20.11|25.79.6","29":"13.18.28","30":"13.18.29","32":"13.18.31","34":"13.18.33","35":"10.20.42|13.18.34","38":"10.21.19","39":"40.3.15|13.18.2","41":"13.17.1","43":"10.15.14|13.15.17","44":"13.19.2","45":"13.18.1","46":"10.15.12","47":"9.8.14|10.11.17","48":"10.9.28|13.20.36","49":"13.19.2","50":"13.21.1","52":"10.15.26","53":"6.2.11"}}];
export default C;
